!QUEEN_ACTOR_HEAD_RIGHT = $F2
!QUEEN_ACTOR_BODY = $F3
!QUEEN_ACTOR_MOUTH_CLOSED = $F5
!QUEEN_ACTOR_MOUTH_STUNNED = $F7
!QUEEN_ACTOR_MOUTH_OPEN = $F6
!QUEEN_ACTOR_PROJECTILE = $F2   ; 03:$7573, the head's right half's id too
!QUEEN_ACTOR_BENT_NECK = $82    ; 03:$6F9F
!QA_SPIT      = !Slots+$140     ; `queenActor_spitA`, $C740, three
!QUEEN_SPIT_N = 3
!QUEEN_OBJS   = 12              ; `queen_objectOAM`'s objects, and the wall's
!QUEEN_WALL_HEAD_N = 5          ; 03:$6E25 `LD B,$05`
; Her states (03:$748C's list), the ones a routine of hers sets by number.
!QUEEN_STATE_FORWARD = $01
!QUEEN_STATE_EXTENDING = $03
!QUEEN_STATE_PREP_RETRACT = $04
!QUEEN_STATE_RETRACTING = $05
!QUEEN_STATE_BACKWARD = $07
!QUEEN_STATE_VOMITING = $0A
!QUEEN_STATE_PICK = $0C
!QUEEN_STATE_PREP_EATING = $0D
!QUEEN_STATE_PROJECTILES = $15
