!QUEEN_HEALTH = $96             ; 03:$6DD9, 150
!QUEEN_STATE_PREP_DEATH = $11   ; 03:$7445
; 1.0 Step 20c: her death.
!QUEEN_STATE_DISINTEGRATE = $12 ; 03:$7ACA
!QUEEN_STATE_DELETE_BODY = $13  ; 03:$7B63
!QUEEN_STATE_ALL_DONE = $16     ; 03:$7BD8
