!QUEEN_BODY_END_L = $80         ; 03:$7BC2 `queenDeath_bodyEnd`'s low byte, $9A80
!QUEEN_BODY_ROW_W = $0B         ; 03:$7BA5: cells a row
!QUEEN_BODY_STEP = $15          ; 03:$7BBD: to the next row's first
