!SLOPE_SHALLOW = $14            ; 01:$7192 `CP $14`
!SLOPE_DIAG   = $3C             ; 01:$7196 `CP $3C`
!SLOPE_STEEP  = $C8             ; 01:$719A `CP $C8`
