+       cmp.b #!ZETA_NEAR               ; $73B3
        bcc .spit
        jmp .out                        ; $73B5 `RET NC`
.spit
        jsr .spawnFireball              ; $73B6
        lda.b #!FLAG_SEEN_FIRED         ; $73B9
