.checkIfHurt
        lda.w !EnWeapon                 ; $73CC
        cmp.b #!EN_TOUCH                ; $73CF: nothing, or Samus
        bcc +
        jmp .standardAction             ; $73D1 `JP NC`
+       cmp.b #!WPN_SCREW               ; $73D4
