        jmp .out
.hurtReaction
        ; $73EB. A missile, but not one going up.
        lda.w !EnWeaponDir              ; $73EB `LD B,A`
        sta.w !MetB
        and.b #$04                      ; $73EF `BIT 2,B`
.upTest                                 ; `zeta kill`'s behaviour fault
        bne .plink                      ; $73F1
        dec.w !Slots+!EN_HEALTH,x       ; $73F6
        bne +
        jmp .death                      ; $73F9
+       lda.b #!SPR_ZETA_8              ; $73FB
        sta.w !Slots+!EN_SPRITE,x
        lda.b #!ZETA_STUN_N             ; $73FF
