.downTest                               ; `zeta shot`'s behaviour fault
        beq .knockLeft                  ; $7415, $7418 `JR $7439`
        lda.w !Slots+!EN_DIRFLAGS,x     ; $741A `SET 1,(HL)`
        ora.b #$02
        sta.w !Slots+!EN_DIRFLAGS,x
        lda.w !Slots+!EN_YPOS,x         ; $741C
        clc
        adc.b #!ZETA_KNOCK
        sta.w !Slots+!EN_YPOS,x
        jsr .coin                       ; $7422 `LD A,($FF04)`
        beq +                           ; $7427
        lda.w !Slots+!EN_DIRFLAGS,x
        ora.b #$01                      ; $7429 `SET 0,(HL)`
