        sep #$20
        lda.w !Slots+!EN_YPOS,x         ; $7548
        cmp.b #!ZETA_BOTTOM             ; $7549
        bcs +
        jmp .out                        ; $754B `RET C`
+       jsl EnemyDeleteSelfLong         ; $754C `CALL $3CA6`
        sep #$20
        lda.b #!FLAG_DEAD               ; $754F
        sta.w !Slots+!EN_FLAG,x
        lda.b #!ZETA_HUSK_GONE          ; $7553
        sta.w !MetState
        jmp .out

.spawnHusk
        stz.w !Slots+!EN_COUNTER,x      ; $7559 `LD (HL),A`
        stz.w !Slots+!EN_STUN,x         ; $755B
        ; $755D `CALL $3DF6`, with no answer for a full array; see `EnAiPipeBug`.
        stx.w !EnParent
        %call0(FirstEmptySlot)
        bcs +
        ldx.w !EnParent
        jmp .out
+       ldy.w !EnParent                 ; X is the husk, Y the Zeta
        sep #$20
        stz.w !Slots+!EN_STATUS,x       ; $7560
        lda.w !Slots+!EN_YPOS,y         ; $7562
        sta.w !Slots+!EN_YPOS,x
        lda.w !Slots+!EN_XPOS,y         ; $7565
        sta.w !Slots+!EN_XPOS,x
        lda.b #!ZETA_HUSK_FLAG          ; $756B
        sta.w !EnAiTmp
        phb                             ; the header is in this bank
        phk
        plb
        ldy.w #ZetaHuskHeader           ; $7568 `LD DE,$759F`
        jsr EnSpawnLong                 ; $7570 `CALL $7235`
        plb
        ldx.w !EnParent
        sep #$20
        lda.w !Slots+!EN_YPOS,x         ; $7573
        sec
        sbc.b #!ZETA_HUSK_DY
        sta.w !Slots+!EN_YPOS,x
        lda.b #!SPR_ZETA_1              ; $757A
        sta.w !Slots+!EN_SPRITE,x
        jmp .out

.appearanceRise
        lda.w !MetState                 ; $757F
        beq +
        jmp .out                        ; $7583 `RET NZ`
+       %call0(MetroidOscillateNarrow)  ; $7584
        sep #$20
        lda.w !EnFrame                  ; $7587
        and.b #$07
        beq +
        jmp .out                        ; $758B `RET NZ`
+       dec.w !Slots+!EN_YPOS,x         ; $758F
        inc.w !Slots+!EN_COUNTER,x      ; $7593
        lda.w !Slots+!EN_COUNTER,x
        cmp.b #!ZETA_RISE_N             ; $7595
        beq +
        jmp .out                        ; $7597 `RET NZ`
+       stz.w !Slots+!EN_COUNTER,x      ; $7598
        lda.b #!MET_STATE_START         ; $759A `INC A`
        sta.w !MetState
        jmp .out

; $75AC `.spawnFireball`: below it and $18 out the way it faces, falling.
; Keeps X.
.spawnFireball
        stx.w !EnParent
        %call0(FirstEmptySlot)          ; $75AC `CALL $3DF6`
        bcs +
        ldx.w !EnParent
        sep #$20
        rts
+       ldy.w !EnParent                 ; X is the fireball, Y the Zeta
        sep #$20
        stz.w !Slots+!EN_STATUS,x       ; $75AF
        lda.w !Slots+!EN_YPOS,y         ; $75B1
        clc
        adc.b #!ZETA_SHOT_OY
        sta.w !Slots+!EN_YPOS,x
        lda.w !Slots+!EN_ATTR,y         ; $75B6
        and.b #$20                      ; $75B9 `BIT 5,A`
        bne +
        lda.w !Slots+!EN_XPOS,y         ; $75BD
        sec
        sbc.b #!ZETA_SHOT_OX
        bra ++
+       lda.w !Slots+!EN_XPOS,y         ; $75C4
        clc
        adc.b #!ZETA_SHOT_OX
++      sta.w !Slots+!EN_XPOS,x
        lda.b #!SPR_ZETA_SHOT           ; $75C9
        sta.w !Slots+!EN_SPRITE,x
        lda.b #!ZETA_SHOT_BASE          ; $75CC
        sta.w !Slots+!EN_BASEATTR,x
        lda.w !Slots+!EN_ATTR,y         ; $75CF `LD A,B`
        sta.w !Slots+!EN_ATTR,x
        lda.b #!FLAG_CHILD              ; $75D4
        sta.w !EnAiTmp
        phb
        phk
        plb
        ldy.w #ZetaShotHeader           ; $75D1 `LD DE,$75E2`
        %call0(EnSpawnShort)            ; $75D9 `CALL $7231`
        plb
        sep #$20
        lda.b #!SFX_ZETA_SHOT           ; $75DC
        sta.w !SfxNoise
        %audio_put_long(!REQ_SFX_NOISE, $0275DE)
        ldx.w !EnParent
        rts

; $7614 `.animateWait`: the tail, $B3 to $B6 and round, every fourth pass.
.animateWait
        lda.w !EnFrame                  ; $7614
        and.b #$03
        bne ++                          ; $7618 `RET NZ`
        lda.w !Slots+!EN_SPRITE,x       ; $761C
        cmp.b #!SPR_ZETA_4              ; $761D
        bne +
        lda.b #!SPR_ZETA_HUSK           ; $7621 `LD (HL),$B2`, one before $B3
        sta.w !Slots+!EN_SPRITE,x
+       inc.w !Slots+!EN_SPRITE,x       ; $7623
++      rts

; $7625 `.animateHurt`: $BA to $BD and round, every pass.
.animateHurt
        lda.w !Slots+!EN_SPRITE,x       ; $7628
        cmp.b #!SPR_ZETA_B              ; $7629
        bne +
        lda.b #!SPR_ZETA_8              ; $762D `LD (HL),$BA`
        sta.w !Slots+!EN_SPRITE,x
+       inc.w !Slots+!EN_SPRITE,x       ; $762F
        rts

; The coin a hurt tosses for its second knockback axis, 02:$7422 and $7445:
; `rDIV`'s low bit, for which `!EnFrame` stands in as in `AlphaCoin`, and
; which the enemy oracle hands across the same way.
; out: A = the coin, Z set for the second arm.
.coin
        lda.w !EnFrame
        and.b #$01                      ; $7425, $7448 `AND $01`
        rts

; 02:$759F `.gammaHuskHeader`: ten header bytes, the spawn number and the AI.
; 02:$75E2 `.fireballHeader`: seven, the spawn number and the AI. Both graded
; against the cartridge by `src/correspond.zig`.
ZetaHuskHeader:
        db $B2,$80,$00,$00,$00,$00,$00,$00,$00,$FF,$06
        dw $7276
ZetaShotHeader:
        db $00,$00,$FF,$00,$00,$00,$FF,$08
        dw $7276

; ---------------------------------------------------------------------------
; 02:$75FF `enAI_zetaMetroid.oscillateWide`: the husk's, on three passes in
; four, three pixels right, nothing, or three left. `.oscillateNarrow` is
; `MetroidOscillateNarrow`, in bank 0 since the Alpha borrowed it.
; ---------------------------------------------------------------------------
MetroidOscillateWide:
        sep #$20
        lda.w !EnFrame                  ; $75FF
        and.b #$03
        beq .out                        ; $7603 `RET Z`
        dec a
        beq .right                      ; $7608
        dec a
        beq .out                        ; $760B `RET Z`
        dec.w !Slots+!EN_XPOS,x         ; $760C
        dec.w !Slots+!EN_XPOS,x
        dec.w !Slots+!EN_XPOS,x
.out
        rts
.right
        inc.w !Slots+!EN_XPOS,x         ; $7610
        inc.w !Slots+!EN_XPOS,x
        inc.w !Slots+!EN_XPOS,x
        rts

; ---------------------------------------------------------------------------
; 02:$7DC6 `metroid_keepOnscreen`: Y no higher than $18, X between $18 and
; $90. Nothing stops it going off the bottom.
; ---------------------------------------------------------------------------
MetroidKeepOnscreen:
        sep #$20
        lda.w !Slots+!EN_YPOS,x         ; $7DCC
        cmp.b #!KEEP_LO                 ; $7DCD `CP B`
        bcs +
        lda.b #!KEEP_LO                 ; $7DD0 `LD (HL),B`
        sta.w !Slots+!EN_YPOS,x
+       lda.w !Slots+!EN_XPOS,x         ; $7DD2
        cmp.b #!KEEP_LO                 ; $7DD3 `CP B`
        bcs +
        lda.b #!KEEP_LO                 ; $7DD6
        sta.w !Slots+!EN_XPOS,x
        rts
+       cmp.b #!KEEP_HI                 ; $7DD8 `CP C`
        bcc +                           ; `RET C`
        lda.b #!KEEP_HI                 ; $7DDB
        sta.w !Slots+!EN_XPOS,x
+       rts

; ---------------------------------------------------------------------------
; 03:$6B44 `enemy_seekSamus`: steer a two-byte vector toward Samus and move
; along it. `+$09` is the Y index and `+$0A` the X index into one speed table,
; each stepped by B toward her -- up to D or down to E, which stop it -- and
; left alone when she is level on that axis; then the table's entry at each is
; added to the position. Both sides of each comparison are biased by $10
; first, in eight bits, as the original's temporaries are ($C43C-$C43F).
; The Zeta's, the Omega's and the larvae's.
;
; in: X = slot offset, !MetB = B, !MetD = D, !MetE = E.
; ---------------------------------------------------------------------------
EnemySeekSamus:
        sep #$20
        rep #$10
        lda.w !Slots+!EN_YPOS,x         ; $6B58
        clc
        adc.b #!SEEK_BIAS
        sta.w !EnAiTmp                  ; $C43C
        lda.w !OnscreenY                ; $6B4D
        clc
        adc.b #!SEEK_BIAS
        sec
        sbc.w !EnAiTmp                  ; $6B60 `SUB (HL)`
        beq .x                          ; $6B61
        bcc .up                         ; $6B63
        lda.w !Slots+!EN_COUNTER,x      ; $6B65: she is below
        cmp.w !MetD                     ; $6B67 `CP D`
        beq .x
        clc
        adc.w !MetB                     ; $6B6A
        sta.w !Slots+!EN_COUNTER,x
        bra .x
.up
        lda.w !Slots+!EN_COUNTER,x      ; $6B6F
        cmp.w !MetE                     ; $6B71 `CP E`
        beq .x
        sec
        sbc.w !MetB                     ; $6B74
        sta.w !Slots+!EN_COUNTER,x
.x
        lda.w !Slots+!EN_XPOS,x         ; $6B53
        clc
        adc.b #!SEEK_BIAS
        sta.w !EnAiTmp                  ; $C43D
        lda.w !OnscreenX                ; $6B47
        clc
        adc.b #!SEEK_BIAS
        sec
        sbc.w !EnAiTmp                  ; $6B7B `SUB (HL)`
        beq .move                       ; $6B7C
        bcc .left                       ; $6B7E
        lda.w !Slots+!EN_STATE,x        ; $6B80: she is right
        cmp.w !MetD                     ; $6B82
        beq .move
        clc
        adc.w !MetB                     ; $6B85
        sta.w !Slots+!EN_STATE,x
        bra .move
.left
        lda.w !Slots+!EN_STATE,x        ; $6B8A
        cmp.w !MetE                     ; $6B8C
        beq .move
        sec
        sbc.w !MetB                     ; $6B8F
        sta.w !Slots+!EN_STATE,x
.move
        %tabp(!SeekSpeedA)              ; $6B97 `LD HL,$6BB1`
        rep #$20
        lda.w !Slots+!EN_COUNTER,x      ; $6B92
        and.w #$00FF
        tay
        sep #$20
        lda [!TabP],y                   ; $6B9B
        clc
        adc.w !Slots+!EN_YPOS,x         ; $6B9F `ADD A,(HL)`
        sta.w !Slots+!EN_YPOS,x
        rep #$20
        lda.w !Slots+!EN_STATE,x        ; $6BA1
        and.w #$00FF
        tay
        sep #$20
        lda [!TabP],y                   ; $6BAA
        clc
        adc.w !Slots+!EN_XPOS,x         ; $6BAE
        sta.w !Slots+!EN_XPOS,x
        rts

; ---------------------------------------------------------------------------
; 1.0 Step 16: 02:$7631 `enAI_omegaMetroid`, and the fireball it spits, which
; runs the same AI in another slot (flag $06).
;
; **The intro is short, and it is one slot's.** An unseen Omega blinks between
; the Zeta's sprite and its own (`XOR $0C`) every fourth pass, once Samus is
; within `!OMEGA_RANGE` across -- measured from sixteen in on both, where the
; seen Omega's test is not -- which freezes her and asks for the fight song.
; On the twenty-fourth blink it becomes the Omega ($BF), thaws her, and starts
; the fight with its flag at `$04`. A seen Omega starts it the next time she is
; in range, with no intro.
;
; The fight is `metroid_state` 1, 2, 4, 5, 6 and 7 (3 is unused):
; - 1 faces her and spits a fireball after sixteen passes, flag `$05`, mouth
;   open ($C1); 2 waits while the fireball lives, wiggling, closing its mouth
;   after $18 passes and wagging its tail $0C more before it faces her again;
;   the fireball's end, or its deletion, is 4, which is 1 again.
; - Every pass of 1, 2 and 4 counts `omega_waitCounter` up; at $40 it **picks a
;   chase**, $0C, $14, $28, $40 or $60 passes long by `omega_chaseTimerIndex`,
;   which steps 1-4 and back to the shortest -- or straight there if her health
;   fell $30 or more since the last pick -- and returns from the AI, as its
;   `POP AF` does.
; - 5 seeks her (`EnemySeekSamus`) and faces her past sixteen pixels either
;   way, until the timer runs out or she crouches, unless the index is 4;
;   6 rises on the backwards curve to $34, two pixels a pass forward; 7 wags
;   its tail $38 passes, and back to 1.
;
; The fireball aims once, by `gamma_getAngle`, flies along
; `gamma_getSpeedVector`, and bursts ($C8 to $CC) where its near probe meets a
; wall above or below; any other wall it passes. It is deleted at the burst's
; end or when the Omega dies, and its deletion in state 2 is 4.
;
; A beam dinks, a screw attack knocks it back as the Alpha's does, and a
; missile **going up or down dinks** (`AND $03`). A missile from behind takes
; three health and stuns it $10 passes, one from in front takes one and stuns
; it three; either shows $C4 (flipping to $C5 on even passes), cries, and
; pushes it five pixels the way the missile went, with no probe, the left
; push not below $10. The stun's end puts back the sprite it covered. There is
; no coin: the Omega does not read `rDIV`.
;
; Its state is the slot's, `metroid_state`, the fight flag, and its five own:
; `omega_stunCounter` ($C462), `omega_tempSpriteType` ($C44F),
; `omega_waitCounter` ($C46F), `omega_samusPrevHealth` ($C470) and
; `omega_chaseTimerIndex` ($C478).
;
; `.unusedProc` (02:$7A06) is reached by nothing and is not ported.
;
; in: X = slot offset.
; ---------------------------------------------------------------------------
EnAiOmega:
        sep #$20
        rep #$10
        %call0(EnemyCollisionResults)   ; $7631 `CALL $7DA0`
        sep #$20
        lda.w !Slots+!EN_FLAG,x         ; $7634
        cmp.b #!FLAG_CHILD              ; $7636 `CP $06`: the fireball
        bne +
        jmp .fireball                   ; $7638
+       lda.w !MetState                 ; $763B
        beq +                           ; $763E
        jsr MetroidKeepOnscreen         ; $763F `CALL NZ,$7DC6`
+       lda.w !OmegaStun                ; $7642
        beq .checkIfHurt                ; $7647
        dec.w !OmegaStun                ; $7649 `DEC (HL)`
        beq .stunEnd                    ; $764A
        lda.w !EnFrame                  ; $764C
        and.b #$01
        bne .out                        ; $7650 `RET NZ`
        lda.w !Slots+!EN_SPRITE,x       ; $7651 `CALL $6B3F`, `enemy_flipSpriteId.now`
        eor.b #$01
        sta.w !Slots+!EN_SPRITE,x
        lda.w !EnWeapon                 ; $7654: only a screw gets past a stun
        cmp.b #!WPN_SCREW               ; $7657
        bcs .out                        ; $7659 `RET NC`
        lda.b #!SFX_BEAM_DINK           ; $765A
        sta.w !Sfx1
        %audio_put_long(!REQ_SFX_SQUARE1, $02765C)
.out
        rep #$30
        rts
.stunEnd
        lda.w !OmegaSprite              ; $7660: the sprite the stun covered
        sta.w !Slots+!EN_SPRITE,x
.checkIfHurt
        lda.w !MetState                 ; $7665
        bne +
        jmp .tryStartingFight           ; $7669
+       lda.w !EnWeapon                 ; $766C
        cmp.b #!EN_TOUCH                ; $766F: nothing, or Samus
        bcc +
        jmp .standardAction             ; $7671 `JP NC`
+       cmp.b #!WPN_SCREW               ; $7674
        beq .screwReaction
        cmp.b #!WPN_MISSILE             ; $7678
        beq .hurtReaction
.plink
        lda.b #!SFX_BEAM_DINK           ; $767C: every beam, and a missile up or down
        sta.w !Sfx1
        %audio_put_long(!REQ_SFX_SQUARE1, $02767E)
        jmp .out
.screwReaction
        %call0(MetroidScrewReaction)    ; $7682
        sep #$20
        lda.b #!SFX_METROID_SCREW       ; $7685
        sta.w !Sfx1
        %audio_put_long(!REQ_SFX_SQUARE1, $027687)
        jmp .out
.hurtReaction
        ; $768B. A missile going right or left: from behind or in front.
        lda.w !EnWeaponDir              ; $768E `LD B,A`
        sta.w !MetB
        and.b #$03                      ; $7690
.vertTest                               ; `omega shot`'s behaviour fault
        beq .plink                      ; $7692
        lda.w !Slots+!EN_ATTR,x         ; $7694
        and.b #$20                      ; $7696 `BIT 5,A`
        bne .facingRight                ; $7698
        lda.w !MetB                     ; $769A `BIT 1,B`: going left, into its back
        and.b #$02
.backTest                               ; `omega kill`'s behaviour fault
        beq .hurtFront                  ; $769C
        bra .hurtBack                   ; $769E
.facingRight
        lda.w !MetB                     ; $76A0 `BIT 0,B`
        and.b #$01
        beq .hurtFront                  ; $76A2
.hurtBack
        lda.w !Slots+!EN_HEALTH,x       ; $76A4 `LD HL,$FFEC`
        sec
        sbc.b #!OMEGA_BACK_HURT         ; $76A8
        bcc .death                      ; $76AA `JR C`
        beq .death                      ; $76AC `JR Z`
        sta.w !Slots+!EN_HEALTH,x       ; $76AE
        lda.b #!OMEGA_STUN_BACK         ; $76AF
        bra .stun                       ; $76B1
.hurtFront
        dec.w !Slots+!EN_HEALTH,x       ; $76B6
        beq .death                      ; $76B7
        lda.b #!OMEGA_STUN_FRONT        ; $76B9
.stun
        sta.w !OmegaStun                ; $76BB
        lda.w !Slots+!EN_SPRITE,x       ; $76C1
        sta.w !OmegaSprite              ; $76C2
        lda.b #!SPR_OMEGA_HURT          ; $76C5
        sta.w !Slots+!EN_SPRITE,x
        lda.b #!SFX_QUEEN_CRY           ; $76C7
        sta.w !SfxNoise
        %audio_put_long(!REQ_SFX_NOISE, $0276C9)
        lda.w !MetB                     ; $76CC `BIT 0,B`: pushed the way it went
        and.b #$01
        beq .knockLeft                  ; $76CE
        lda.w !Slots+!EN_XPOS,x         ; $76D0
        clc
        adc.b #!OMEGA_KNOCK
        sta.w !Slots+!EN_XPOS,x         ; $76D4
        jmp .out
.knockLeft
        lda.w !Slots+!EN_XPOS,x         ; $76D7
        sec
        sbc.b #!OMEGA_KNOCK
        cmp.b #!OMEGA_KNOCK_LEFT        ; $76DB, after the push
        bcs +
        jmp .out                        ; $76DD `RET C`
+       sta.w !Slots+!EN_XPOS,x         ; $76DE
        jmp .out

.death
        ; $76E1. The last missile, as the Alpha's, the Gamma's and the Zeta's.
        stz.w !Slots+!EN_COUNTER,x      ; $76E2
        stz.w !Slots+!EN_STATE,x        ; $76E4
        stz.w !OmegaWait                ; $76E6
        stz.w !OmegaChaseIx             ; $76E9
        lda.b #!MET_STATE_DYING         ; $76EC
        sta.w !MetState
        lda.b #!SPR_EXP_BIG             ; $76F1
        sta.w !Slots+!EN_SPRITE,x
        lda.b #!SFX_OMEGA_KILLED        ; $76F5
        sta.w !SfxNoise
        %audio_put_long(!REQ_SFX_NOISE, $0276F7)
        lda.b #!SONG_METROID_KILLED     ; $76FA, the jingle
        sta.w !MetSong
        %audio_put_long(!REQ_SONG, $0276FC)
        lda.b #!MET_FIGHT_DIED          ; $76FF
        sta.w !MetFight
        sta.w !Slots+!EN_FLAG,x         ; $7704: the same $02, and it is dead
        ; $7706 and $770E, `SUB $01 / DAA` on each count.
        sed
        sec
        lda.w !MetReal
        sbc.b #$01
        sta.w !MetReal
        sec
        lda.w !MetDisp
        sbc.b #$01
        sta.w !MetDisp
        cld
        lda.b #!MET_SHUFFLE             ; $7716
        sta.w !Shuffle
        jsl EarthquakeCheckLong         ; $771B `CALL $3C92`, which takes X
        jmp .out

.standardAction
        lda.w !Slots+!EN_DIRFLAGS,x     ; $771F
        inc a                           ; $7721: $FF is "not being knocked back"
        bne +
        jmp .handleStates               ; $7722
+       %call0(MetroidScrewKnockback)   ; $7724
        sep #$20
        lda.w !MetScrewDone             ; $7727
        bne +
        jmp .out                        ; $772C `RET Z`
+       stz.w !MetScrewDone             ; $772D
        lda.b #$FF                      ; $772F
        sta.w !Slots+!EN_DIRFLAGS,x
        stz.w !OmegaWait                ; $7733
        lda.b #!OMEGA_SCREW_IDX         ; $7737
        sta.w !OmegaChaseIx
        lda.b #!OMEGA_SCREW_CHASE       ; $773C
        sta.w !Slots+!EN_GENVAR,x
        lda.b #!OMEGA_VEC0              ; $7740
        sta.w !Slots+!EN_COUNTER,x
        sta.w !Slots+!EN_STATE,x        ; $7744
        lda.b #!SPR_OMEGA_5             ; $7748
        sta.w !Slots+!EN_SPRITE,x
        lda.b #!OMEGA_CHASE             ; $774C
        sta.w !MetState
        jmp .out

.state7
        ; $7752. $38 passes of the tail, then 1.
        inc.w !Slots+!EN_COUNTER,x
        lda.w !Slots+!EN_COUNTER,x
        cmp.b #!OMEGA_WAIT_N            ; $7757
.waitTest                               ; `omega`'s behaviour fault
        beq +
        jsr .animateTail                ; $775B
        jmp .out
+       stz.w !Slots+!EN_COUNTER,x      ; $775F
        lda.b #!MET_STATE_START         ; $7761
        sta.w !MetState
        jmp .out

.state4
        ; $7767. Back to 1, mouth shut.
        stz.w !Slots+!EN_COUNTER,x      ; $7768
        stz.w !Slots+!EN_STATE,x        ; $776A
        lda.b #!MET_STATE_START         ; $776C
        sta.w !MetState
.closeMouth
        lda.b #!SPR_OMEGA_1             ; $7771
        sta.w !Slots+!EN_SPRITE,x
        jmp .out

.animateState2
        ; $7776. The tail for $24 more passes, then face her.
        lda.w !Slots+!EN_STATE,x
        cmp.b #!OMEGA_TAIL_N            ; $777A
        beq +
        inc.w !Slots+!EN_STATE,x        ; $777E
        jsr .animateTail                ; $777F
        jmp .out
+       jsr .faceSamus                  ; $7783
        jmp .out

.handleStates
        lda.w !MetState                 ; $7787
        cmp.b #!OMEGA_CHASE             ; $778A
        bne +
        jmp .state5
+       cmp.b #!OMEGA_RISE              ; $778E
        bne +
        jmp .state6
+       cmp.b #!OMEGA_WAIT              ; $7792
        beq .state7
        ; $7796 `CALL $79A8`, `.selectChaseTimer`. Its pick ends in `POP AF /
        ; RET`, which returns from the AI; here that arm jumps out.
        lda.w !OmegaWait                ; $79A8
        cmp.b #!OMEGA_TIMER_N           ; $79AC
        bne +
        jmp .selectChase                ; $79AE
+       inc.w !OmegaWait                ; $79B0
        lda.w !MetState                 ; $7799
        cmp.b #!OMEGA_REST              ; $779C
        beq .state4
        dec a                           ; $77A0
        bne +
        jmp .state1                     ; $77A1
+       ; $77A4. State 2: until the fireball is gone.
        lda.w !EnTotal                  ; $77A4 `numEnemies.total`
        dec a
        beq .state4                     ; $77A8
        lda.w !Slots+!EN_COUNTER,x      ; $77AC
        cmp.b #!OMEGA_MOUTH_N           ; $77B0 `CP B`
        beq .animateState2              ; $77B1
        inc.w !Slots+!EN_COUNTER,x      ; $77B3
        lda.w !Slots+!EN_COUNTER,x
        cmp.b #!OMEGA_MOUTH_N           ; $77B5
        beq .closeMouth                 ; $77B6
        lda.w !EnFrame                  ; $77B8 `CALL $6B4E`, `enemy_flipSpriteId_2Bits.twoFrame`
        and.b #$01
        bne +
        lda.w !Slots+!EN_SPRITE,x       ; 02:$6B53
        eor.b #$03
        sta.w !Slots+!EN_SPRITE,x
+       jmp .out

.state5
        ; $77BC. The chase.
        dec.w !Slots+!EN_GENVAR,x       ; $77BF
        beq .toRise                     ; $77C0
        lda.w !OmegaChaseIx             ; $77C2
        cmp.b #!OMEGA_FORCE_IDX         ; $77C5
        beq .chaseSamus                 ; $77C7
        lda.b !Pose                     ; $77C9 `samusPose`
        cmp.b #!POSE_CROUCH             ; $77CC
        beq .toRise                     ; $77CE
.chaseSamus
        lda.b #!SEEK_STEP               ; $77D0 `LD B,$02`
        sta.w !MetB
        lda.b #!SEEK_MAX                ; $77D2 `LD DE,$2000`
        sta.w !MetD
        lda.b #!SEEK_MIN
        sta.w !MetE
        jsr EnemySeekSamus              ; $77D5 `CALL $3CBA`, `enemy_seekSamus`'s far call
        sep #$20
        lda.w !OnscreenX                ; $77DB
        sec
        sbc.w !Slots+!EN_XPOS,x         ; $77DE `SUB (HL)`
        bcc .chaseLeft                  ; $77DF `JR C`
        cmp.b #!OMEGA_FACE              ; $77E1
        bcs +
        jmp .out                        ; $77E3
+       lda.b #$20                      ; $77E5 OAMF_XFLIP: facing her
        sta.w !Slots+!EN_ATTR,x
        jmp .out
.chaseLeft
        cmp.b #!OMEGA_FACE_L            ; $77EB
        bcc +
        jmp .out                        ; $77ED
+       stz.w !Slots+!EN_ATTR,x         ; $77EF
        jmp .out
.toRise
        lda.b #!OMEGA_RISE              ; $77F3
        sta.w !MetState
        stz.w !Slots+!EN_GENVAR,x       ; $77F9
        stz.w !Slots+!EN_COUNTER,x      ; $77FB
        stz.w !Slots+!EN_STATE,x        ; $77FD
        jmp .out

.state6
        ; $7800. Up on the backwards curve, forward two pixels, to $34.
        lda.b #!EN_YPOS                 ; `LD HL,$FFE1`
        sta.w !EnAccelField
        stz.w !EnAccelField+1
        %call0(EnemyAccelBackwards)     ; $7803 `CALL $6AAE`
        sep #$20
        lda.w !Slots+!EN_YPOS,x         ; $7806 `LD A,(HL+)`
        cmp.b #!OMEGA_TOP               ; $7807
        bcc .toWait                     ; $7809
        lda.w !Slots+!EN_ATTR,x         ; $780B
        and.b #$20                      ; $780D `BIT 5,A`
        bne +
        dec.w !Slots+!EN_XPOS,x         ; $7811
        dec.w !Slots+!EN_XPOS,x
        jmp .out
+       inc.w !Slots+!EN_XPOS,x         ; $7814
        inc.w !Slots+!EN_XPOS,x
        jmp .out
.toWait
        lda.b #!OMEGA_WAIT              ; $7817
        sta.w !MetState
        stz.w !Slots+!EN_GENVAR,x       ; $781D: the curve's index
        lda.b #!SPR_OMEGA_1             ; $781F
        sta.w !Slots+!EN_SPRITE,x
        jmp .out

.state1
        ; $7824. Face her, and spit on the sixteenth pass.
        jsr .faceSamus
        inc.w !Slots+!EN_COUNTER,x      ; $782A
        lda.w !Slots+!EN_COUNTER,x
        cmp.b #!OMEGA_FIRE_N            ; $782C
        beq +
        jmp .out                        ; $782E `RET NZ`
+       stz.w !Slots+!EN_COUNTER,x      ; $782F
        jsr .spawnFireball              ; $7831
        lda.b #!MET_STATE_FIGHT         ; $7834
        sta.w !MetState
        lda.b #!FLAG_SEEN_FIRED         ; $7839
        sta.w !Slots+!EN_FLAG,x
        lda.b #!SPR_OMEGA_3             ; $783D
        sta.w !Slots+!EN_SPRITE,x
        lda.b #!SFX_ZETA_SHOT           ; $7841, `metroidFireball`
        sta.w !SfxNoise
        %audio_put_long(!REQ_SFX_NOISE, $027843)
        jmp .out

; $7847 `.fireball`: aimed once, along the Gamma's twenty-four directions.
.fireball
        lda.w !MetFight                 ; $7847
        cmp.b #!MET_FIGHT_DIED          ; $784A
        bne +
        jmp .shotDelete                 ; $784C
+       lda.w !Slots+!EN_SPRITE,x       ; $784F
        cmp.b #!SPR_OMEGA_BURST         ; $7851
        bcc +
        jmp .shotBurst                  ; $7853 `JR NC`
+       lda.w !Slots+!EN_COUNTER,x      ; $7855
        bne +                           ; $785A
        lda.b #$01                      ; $785C
        sta.w !Slots+!EN_COUNTER,x
        jsr GammaGetAngle               ; $785E, 00:$3D20's far call
+       jsr GammaGetSpeedVector         ; $7861, 00:$3D48's far call
        sep #$20
        lda.w !MetB                     ; $7864
        beq .shotX                      ; $7866
        bpl .shotDown                   ; $7868 `BIT 7,B`
        and.b #$7F                      ; $786C `RES 7,B`
        sta.w !MetB
        lda.w !Slots+!EN_YPOS,x         ; $786E
        sec
        sbc.w !MetB                     ; $7872 `SUB B`
        sta.w !Slots+!EN_YPOS,x
        %call0(EnCollideUpNear)         ; $7874 `CALL $4BC2`
        sep #$20
        lda.w !EnBgResult               ; $7877
        and.b #$08                      ; $787A `BIT 3,A`
        bne .shotHit                    ; $787C
        bra .shotX                      ; $787E
.shotDown
        lda.w !Slots+!EN_YPOS,x         ; $7880
        clc
        adc.w !MetB                     ; $7884 `ADD A,B`
        sta.w !Slots+!EN_YPOS,x
        %call0(EnCollideDownNear)       ; $7886 `CALL $49BA`
        sep #$20
        lda.w !EnBgResult               ; $7889
        and.b #$02                      ; $788C `BIT 1,A`
        bne .shotHit                    ; $788E
.shotX
        lda.w !MetC                     ; $7893 `BIT 7,C`
        bpl +
        and.b #$7F                      ; $7897 `RES 7,C`
        sta.w !MetC
        lda.w !Slots+!EN_XPOS,x         ; $7899
        sec
        sbc.w !MetC                     ; $789A `SUB C`
        bra ++
+       lda.w !Slots+!EN_XPOS,x         ; $789D
        clc
        adc.w !MetC                     ; $789E `ADD A,C`
++      sta.w !Slots+!EN_XPOS,x         ; $789F
        lda.w !EnFrame                  ; $78A0
        and.b #$03
        beq +
        jmp .out                        ; $78A4 `RET NZ`
+       lda.w !Slots+!EN_SPRITE,x       ; $78A5 `CALL $6B3F`, `enemy_flipSpriteId.now`
        eor.b #$01
        sta.w !Slots+!EN_SPRITE,x
        jmp .out
.shotHit
        ; $78A9. `LD ($C42D),A`, a byte nothing reads, is not ported.
        stz.w !Slots+!EN_COUNTER,x      ; $78B0
        stz.w !Slots+!EN_STATE,x        ; $78B2
        lda.b #!SPR_OMEGA_BURST         ; $78B4
        sta.w !Slots+!EN_SPRITE,x
        jmp .out
.shotBurst
        lda.w !Slots+!EN_SPRITE,x       ; $78B9
        cmp.b #!SPR_OMEGA_BURST_END     ; $78BD
        beq .shotDelete                 ; $78BF
        lda.w !EnFrame                  ; $78C1
        and.b #$01
        beq +
        jmp .out                        ; $78C5 `RET NZ`
+       inc.w !Slots+!EN_SPRITE,x       ; $78C6
        jmp .out
.shotDelete
        jsl EnemyDeleteSelfLong         ; $78C8 `CALL $3CA6`
        sep #$20
        lda.b #$FF                      ; $78CB
        sta.w !Slots+!EN_FLAG,x
        lda.w !MetState                 ; $78CF
        cmp.b #!MET_STATE_FIGHT         ; $78D3
        beq +
        jmp .out                        ; $78D5 `RET NZ`
+       lda.b #!OMEGA_REST              ; $78D6
        sta.w !MetState
        jmp .out

.tryStartingFight
        lda.w !Slots+!EN_FLAG,x         ; $78DC
        cmp.b #!FLAG_ACTIVE_SEEN        ; $78DE: seen before, so no intro
        bne +
        jmp .quickIntro                 ; $78E0
+       lda.w !Cutscene                 ; $78E3
        bne .introBlink                 ; $78E7
        lda.w !Slots+!EN_XPOS,x         ; $78E9
        clc
        adc.b #!OMEGA_RANGE_BIAS        ; $78ED
        sta.w !MetB                     ; $78EF `LD B,A`
        lda.w !OnscreenX                ; $78F0 `samus_onscreenXPos`
        clc
        adc.b #!OMEGA_RANGE_BIAS        ; $78F3
        sec
        sbc.w !MetB                     ; $78F5 `SUB B`
        bcs +                           ; $78F6 `JR NC`
        eor.b #$FF                      ; $78F8 `CPL : INC A`
        inc a
+       cmp.b #!OMEGA_RANGE             ; $78FA
        bcc +
        jmp .out                        ; $78FC `RET NC`
+       lda.b #$01                      ; $78FD
        sta.w !Cutscene                 ; Samus freezes
        lda.b #!SONG_METROID            ; $7902, with no `songPlaying` guard
        sta.w !MetSong
        %audio_put_long(!REQ_SONG, $027904)
        lda.b #$01                      ; $7907
        sta.w !MetFight
.introBlink
        lda.w !EnFrame                  ; $790C
        and.b #$03
        beq +
        jmp .out                        ; $7910 `RET NZ`
+       inc.w !Slots+!EN_COUNTER,x      ; $7914
        lda.w !Slots+!EN_COUNTER,x
        cmp.b #!OMEGA_INTRO_N           ; $7916
        bne +
        jmp .startFight                 ; $7918
+       lda.w !Slots+!EN_SPRITE,x       ; $791B
        eor.b #!OMEGA_INTRO_XOR         ; $791D
        sta.w !Slots+!EN_SPRITE,x
