.quickIntro
        lda.b #!SPR_OMEGA_1             ; $7950
        sta.w !Slots+!EN_SPRITE,x
        lda.w !OnscreenX                ; $7957
        sec
        sbc.w !Slots+!EN_XPOS,x         ; $795A `SUB (HL)`
        bcs +                           ; $795B
        eor.b #$FF
        inc a
+       cmp.b #!OMEGA_RANGE             ; $795F
        bcc +
        jmp .out                        ; $7961 `RET NC`
+       stz.w !Slots+!EN_GENVAR,x       ; $7963
        stz.w !Slots+!EN_COUNTER,x      ; $7965
        stz.w !Slots+!EN_STATE,x        ; $7967
        stz.w !OmegaStun                ; $7969
        stz.w !OmegaWait                ; $796C
        stz.w !OmegaChaseIx             ; $796F
        lda.b #!MET_STATE_START         ; $7972 `INC A`
        sta.w !MetState
        lda.b #$01                      ; $7976
        sta.w !MetFight
        lda.b #$FF                      ; $797B
        sta.w !Slots+!EN_DIRFLAGS,x
        lda.w !AudReply+6               ; $797F `songPlaying`
        cmp.b #!SONG_METROID            ; $7982
        bne +
        jmp .out                        ; $7984 `RET Z`
+       lda.b #!SONG_METROID            ; $7985
        sta.w !MetSong
        %audio_put_long(!REQ_SONG, $027987)
        jmp .out

.startFight
        stz.w !Slots+!EN_COUNTER,x      ; $798B `LD (HL),A`
        lda.b #!SPR_OMEGA_1             ; $798D
        sta.w !Slots+!EN_SPRITE,x
        stz.w !Cutscene                 ; $7992: Samus thaws
        lda.b #!MET_STATE_START         ; $7995 `INC A`
        sta.w !MetState
        lda.b #!FLAG_ACTIVE_SEEN        ; $7999: seen, so no intro next time
        sta.w !Slots+!EN_FLAG,x
        jmp .out

.selectChase
        ; $79B2. Once every $41 passes: the next chase's length.
        stz.w !OmegaWait                ; $79B2 `LD (HL),$00`
        lda.w !OmegaPrevHp              ; $79B7
        sec
        sbc.w !HealthLo                 ; $79BA `SUB (HL)`, $D051
        cmp.b #!OMEGA_HURT_BIG          ; $79BB
        bcs .chaseDefault               ; $79BD `JR NC`
        inc.w !OmegaChaseIx             ; $79C2
        lda.w !OmegaChaseIx
        dec a                           ; $79C4
        beq .chase1
        dec a                           ; $79C7
        beq .chase2
        dec a                           ; $79CA
        beq .chase3
        dec a                           ; $79CD
        beq .chase4
.chaseDefault
        stz.w !OmegaChaseIx             ; $79D0
        lda.b #!OMEGA_CHASE_0           ; $79D4
        bra .chaseSet
.chase1
        lda.b #!OMEGA_CHASE_1           ; $79D8
        bra .chaseSet
.chase2
        lda.b #!OMEGA_CHASE_2           ; $79DC
        bra .chaseSet
.chase3
        lda.b #!OMEGA_CHASE_3           ; $79E0
        bra .chaseSet
.chase4
        lda.b #!OMEGA_CHASE_4           ; $79E4
.chaseSet
        sta.w !Slots+!EN_GENVAR,x       ; $79E6
        lda.w !HealthLo                 ; $79E8
        sta.w !OmegaPrevHp              ; $79EB
        lda.b #!OMEGA_VEC0              ; $79EE
        sta.w !Slots+!EN_COUNTER,x
        sta.w !Slots+!EN_STATE,x        ; $79F2
        lda.b #!SPR_OMEGA_5             ; $79F6
        sta.w !Slots+!EN_SPRITE,x
        lda.b #!SFX_OMEGA_CHASE         ; $79FA
        sta.w !Sfx1
        %audio_put_long(!REQ_SFX_SQUARE1, $0279FC)
        lda.b #!OMEGA_CHASE             ; $79FF
        sta.w !MetState
        jmp .out                        ; $7A04 `POP AF / RET`

; $7922 `.spawnFireball`: level with it and $10 out the way it faces.
; Keeps X.
.spawnFireball
        stx.w !EnParent
        %call0(FirstEmptySlot)          ; $7922 `CALL $3DF6`
        bcs +
        ldx.w !EnParent
        sep #$20
        rts
+       ldy.w !EnParent                 ; X is the fireball, Y the Omega
        sep #$20
        stz.w !Slots+!EN_STATUS,x       ; $7925
        lda.w !Slots+!EN_YPOS,y         ; $7927
        sta.w !Slots+!EN_YPOS,x
        lda.w !Slots+!EN_ATTR,y         ; $792A `LD B,A`
        and.b #$20                      ; $792D `BIT 5,A`
        bne +
        lda.w !Slots+!EN_XPOS,y         ; $7931
        sec
        sbc.b #!OMEGA_SHOT_OX
        bra ++
+       lda.w !Slots+!EN_XPOS,y         ; $7938
        clc
        adc.b #!OMEGA_SHOT_OX
++      sta.w !Slots+!EN_XPOS,x         ; $793C
        lda.b #!SPR_OMEGA_SHOT          ; $793D
        sta.w !Slots+!EN_SPRITE,x
        stz.w !Slots+!EN_BASEATTR,x     ; $7940
        lda.w !Slots+!EN_ATTR,y         ; $7942 `LD A,B`
        sta.w !Slots+!EN_ATTR,x
        lda.b #!FLAG_CHILD              ; $7947
        sta.w !EnAiTmp
        phb
        phk
        plb
        ldy.w #OmegaShotHeader          ; $7944 `LD DE,$799E`
        %call0(EnSpawnShort)            ; $794C `CALL $7231`
        plb
        ldx.w !EnParent
        sep #$20
        rts

; $7A32 `.faceSamus`, falling through into `.animateTail` as the original's
; does.
.faceSamus
        lda.w !OnscreenX                ; $7A35
        sec
        sbc.w !Slots+!EN_XPOS,x         ; $7A38 `SUB (HL)`
        bcs +                           ; $7A39
        lda.b #$00                      ; $7A3B `XOR A`
        bra ++
+       lda.b #$20                      ; $7A3E OAMF_XFLIP
++      sta.w !Slots+!EN_ATTR,x         ; $7A40
; $7A42 `.animateTail`: $BF and $C0, every fourth pass.
.animateTail
        lda.w !EnFrame                  ; $7A42
        and.b #$03
        bne +                           ; $7A46 `RET NZ`
        lda.w !Slots+!EN_SPRITE,x       ; $7A4A
        eor.b #!OMEGA_TAIL_XOR          ; $7A4B
        sta.w !Slots+!EN_SPRITE,x
+       rts

; 02:$799E `.fireballHeader`: seven header bytes, the spawn number and the AI.
; Graded against the cartridge by `src/correspond.zig`.
OmegaShotHeader:
        db $00,$00,$FF,$00,$00,$00,$FF,$08
        dw $7631

; ---------------------------------------------------------------------------
; 1.0 Step 17: 02:$7A4F `enAI_normalMetroid`, the larval Metroid of the final
; area.
;
; **Latched** (`+$07` set) it follows `larva_latchState`, which is global:
; - 2, on her: it sits where she is, and a bomb (`$09`) makes it 1;
; - 1, flying off: up and left three pixels a pass, each axis refused past $10
;   or into a wall by the far-wide probe, for $18 passes, holding
;   `larva_bombState` at 2 so no other larva latches on meanwhile;
; - 0, or the fly-off's end: everything cleared and the seek vector at rest.
; The drain itself is Samus's side: its damage byte is $FE, which
; `ApplyDamageLarva` takes as three units every eighth frame.
;
; **Not latched**, a hurt shows $CF for three passes first. Then:
; - **frozen**, it thaws itself through `EnemyAnimateIce_call`, and at the
;   thaw it is $CE again with five health and the vector at rest. A missile
;   takes one health, and the fifth kills it; ice refreezes it; any other beam
;   dinks, and a touch does nothing;
; - **free**, it blinks between $A0 and $CE every fourth pass. Touching her
;   latches it (fly-off, if another is flying off her); a screw attack or a
;   bomb knocks it back as the Alpha's does; ice freezes it, $44 on the
;   counter; any other shot, a missile included, dinks. Untouched, it rides a
;   screw knockback out, or seeks her one step a pass and backs out of walls
;   (`MetroidCorrectPosition`).
;
; The kill is not the other species' -- no `metroid_state`, no fight, no
; jingle: the slot explodes as an ordinary enemy's does (`+$0E` $10, no drop)
; with both counts down one, the shuffle timer and the quake check.
;
; in: X = slot offset.
; ---------------------------------------------------------------------------
EnAiLarva:
        sep #$20
        rep #$10
        %call0(EnemyCollisionResults)   ; $7A4F `CALL $7DA0`
        sep #$20
        lda.w !Slots+!EN_GENVAR,x       ; $7A52
        bne +
        jmp .unlatchedActions           ; $7A55
+       jsr .animate                    ; $7A57
        lda.w !LarvaLatch               ; $7A5A
        beq .restart                    ; $7A5E
        dec a
        beq .unlatch                    ; $7A61
        ; $7A63: state 2, on her.
        lda.w !OnscreenY                ; $7BD9 `.stayAttached`
        sta.w !Slots+!EN_YPOS,x
        lda.w !OnscreenX                ; $7BE0
        sta.w !Slots+!EN_XPOS,x
        lda.w !EnWeapon                 ; $7A66
        cmp.b #!WPN_BOMB                ; $7A69
.bombTest                               ; `larva bomb`'s behaviour fault
        bne .out                        ; $7A6B `RET NZ`
        dec.w !LarvaLatch               ; $7A6F
.out
        rep #$30
        rts
.unlatch
        inc.w !Slots+!EN_COUNTER,x      ; $7A74
        lda.w !Slots+!EN_COUNTER,x
        cmp.b #!LARVA_FLY_N             ; $7A76
        beq .restart                    ; $7A78
        lda.b #!LARVA_BOMBED            ; $7A7A
        sta.w !LarvaBomb
        lda.w !Slots+!EN_YPOS,x         ; $7A7F
        sec
        sbc.b #!LARVA_FLY_STEP          ; $7A81
        cmp.b #!LARVA_EDGE              ; $7A83
        bcc .flyLeft                    ; $7A85
        sta.w !Slots+!EN_YPOS,x         ; $7A87
        %call0(EnCollideUpFarWide)      ; $7A89 `CALL $4D04`
        sep #$20
        lda.w !EnBgResult               ; $7A8C
        and.b #$08                      ; $7A8F `BIT 3,A`
        beq .flyLeft                    ; $7A91
        lda.w !EnYMirror                ; $7A93
        sta.w !Slots+!EN_YPOS,x
.flyLeft
        lda.w !Slots+!EN_XPOS,x         ; $7A98
        sec
        sbc.b #!LARVA_FLY_STEP          ; $7A9A
        cmp.b #!LARVA_EDGE              ; $7A9C
        bcc .out                        ; $7A9E `RET C`
        sta.w !Slots+!EN_XPOS,x         ; $7A9F
        %call0(EnCollideLeftFarWide)    ; $7AA1 `CALL $490F`
        sep #$20
        lda.w !EnBgResult               ; $7AA4
        and.b #$04                      ; $7AA7 `BIT 2,A`
        beq .out                        ; $7AA9 `RET Z`
        lda.w !EnXMirror                ; $7AAA
        sta.w !Slots+!EN_XPOS,x
        bra .out
.restart
        stz.w !LarvaBomb                ; $7AB1
        stz.w !Slots+!EN_GENVAR,x       ; $7AB4
        stz.w !LarvaLatch               ; $7AB6
        lda.b #!LARVA_VEC0              ; $7AB9
        sta.w !Slots+!EN_COUNTER,x
        sta.w !Slots+!EN_STATE,x        ; $7ABD
        bra .out

.unlatchedActions
        lda.w !LarvaHurtN               ; $7AC0
        beq +                           ; $7AC5
        dec.w !LarvaHurtN               ; $7AC7
        bne .out                        ; $7AC8 `RET NZ`
        lda.b #!SPR_LARVA_2             ; $7AC9
        sta.w !Slots+!EN_SPRITE,x
+       lda.w !Slots+!EN_ICE,x          ; $7ACD
        bne +
        jmp .unfrozenActions            ; $7AD0
+       %call0(EnemyAnimateIce_call)    ; $7AD2 `CALL $565F`
        sep #$20
        lda.w !Slots+!EN_ICE,x          ; $7AD5
        beq .unfreeze                   ; $7AD8
        lda.w !EnWeapon                 ; $7ADA
        cmp.b #!EN_TOUCH                ; $7ADD
        bcs .out2                       ; $7ADF `RET NC`: nothing, or Samus
        cmp.b #!WPN_MISSILE             ; $7AE0
        beq .hurtReaction               ; $7AE2
        dec a
        bne .plink                      ; $7AE4
        jmp .freeze                     ; $7AE5 `JP Z`
.plink
        lda.b #!SFX_BEAM_DINK           ; $7AE8
        sta.w !Sfx1
        %audio_put_long(!REQ_SFX_SQUARE1, $027AEA, $027B60)
.out2                                   ; `.out`, again, within a branch's reach
        rep #$30
        rts
.unfreeze
        lda.b #!LARVA_VEC0              ; $7AEE
        sta.w !Slots+!EN_COUNTER,x
        sta.w !Slots+!EN_STATE,x        ; $7AF2
        lda.b #!SPR_LARVA_2             ; $7AF4
        sta.w !Slots+!EN_SPRITE,x
        lda.b #!LARVA_HEALTH            ; $7AF8
        sta.w !Slots+!EN_HEALTH,x
        bra .out2
.hurtReaction
        dec.w !Slots+!EN_HEALTH,x       ; $7B00
.healthTest                             ; `larva kill`'s behaviour fault
        beq .death                      ; $7B03
        lda.b #!LARVA_HURT_N            ; $7B05
        sta.w !LarvaHurtN
        lda.b #!SPR_LARVA_HURT          ; $7B0A
        sta.w !Slots+!EN_SPRITE,x
        lda.b #!SFX_METROID_HURT        ; $7B0E
        sta.w !SfxNoise
        %audio_put_long(!REQ_SFX_NOISE, $027B10)
        jmp .out
.death
        stz.w !Slots+!EN_COUNTER,x      ; $7B15
        stz.w !LarvaBomb                ; $7B17
        stz.w !LarvaLatch               ; $7B1A
        lda.b #!FLAG_DEAD               ; $7B1D
        sta.w !Slots+!EN_FLAG,x
        lda.b #!LARVA_EXPLODE           ; $7B21
        sta.w !Slots+!EN_EXPLODE,x
        lda.b #!SFX_METROID_KILLED      ; $7B25
        sta.w !SfxNoise
        %audio_put_long(!REQ_SFX_NOISE, $027B27)
        ; $7B2E and $7B36, `SUB $01 / DAA` on each count.
        sed
        sec
        lda.w !MetReal
        sbc.b #$01
        sta.w !MetReal
        sec
        lda.w !MetDisp
        sbc.b #$01
        sta.w !MetDisp
        cld
        lda.b #!MET_SHUFFLE             ; $7B3A
        sta.w !Shuffle
        jsl EarthquakeCheckLong         ; $7B3F `CALL $3C92`, which takes X
        jmp .out

.unfrozenActions
        jsr .animate                    ; $7B43
        lda.w !EnWeapon                 ; $7B46
        cmp.b #$FF                      ; $7B49: not hit
        beq .standardAction
        cmp.b #!EN_TOUCH                ; $7B4E
        beq .touchReaction
        cmp.b #!WPN_SCREW               ; $7B53
        beq .screwReaction
        cmp.b #!WPN_BOMB                ; $7B57
        beq .screwReaction              ; `.bombReaction`, the same code
        dec a
        beq .freeze                     ; $7B5C
        jmp .plink                      ; $7B5E, its own copy of the dink
.touchReaction
        lda.w !LarvaBomb                ; $7B64
        cmp.b #!LARVA_BOMBED            ; $7B68
        beq .flyOff                     ; $7B6A
        cmp.b #!LARVA_TOUCHED           ; $7B6C
        beq +                           ; $7B6E
        lda.b #!LARVA_TOUCHED           ; $7B70
        sta.w !LarvaBomb
+       lda.b #!LARVA_LATCHED           ; $7B75
        bra +
.flyOff
        lda.b #!LARVA_FLY_AWAY          ; $7B79
+       sta.w !LarvaLatch               ; $7B7B
.latchOn                                ; `larva`'s behaviour fault
        lda.b #$01                      ; $7B7E
        sta.w !Slots+!EN_GENVAR,x
        stz.w !Slots+!EN_COUNTER,x      ; $7B83
        jmp .out
.screwReaction
        stz.w !Slots+!EN_COUNTER,x      ; $7B87
        %call0(MetroidScrewReaction)    ; $7B89
        sep #$20
        lda.b #!SFX_METROID_SCREW       ; $7B8C
        sta.w !Sfx1
        %audio_put_long(!REQ_SFX_SQUARE1, $027B8E)
        jmp .out
.freeze
        lda.b #!SFX_METROID_SCREW       ; $7B92
        sta.w !Sfx1
        %audio_put_long(!REQ_SFX_SQUARE1, $027B94)
        lda.b #!LARVA_STUN_ICE          ; $7B97
        sta.w !Slots+!EN_STUN,x
        lda.b #!LARVA_ICE               ; $7B9B
        sta.w !Slots+!EN_ICE,x
        stz.w !Slots+!EN_STATUS,x       ; $7BA0
        jmp .out
.standardAction
        lda.w !Slots+!EN_DIRFLAGS,x     ; $7BA3
        inc a                           ; $7BA5: $FF is "not being knocked back"
        beq .seek                       ; $7BA6
        %call0(MetroidScrewKnockback)   ; $7BA8
        sep #$20
        lda.w !MetScrewDone             ; $7BAB
        bne +
        jmp .out                        ; $7BB0 `RET Z`
+       stz.w !MetScrewDone             ; $7BB1
        lda.b #$FF                      ; $7BB3
        sta.w !Slots+!EN_DIRFLAGS,x
        lda.b #!LARVA_VEC0              ; $7BB7
        sta.w !Slots+!EN_COUNTER,x
        sta.w !Slots+!EN_STATE,x        ; $7BBB
        jmp .out
.seek
        lda.b #!LARVA_SEEK_STEP         ; $7BC0 `LD B,$01`
        sta.w !MetB
        lda.b #!LARVA_SEEK_MAX          ; $7BC2 `LD DE,$1E02`
        sta.w !MetD
        lda.b #!LARVA_SEEK_MIN
        sta.w !MetE
        jsr EnemySeekSamus              ; $7BC5 `CALL $3CBA`, `enemy_seekSamus`'s far call
        jsr MetroidCorrectPosition      ; $7BC8 `CALL $7CDD`
        jmp .out

; $7BCC `.animate`: $A0 and $CE, every fourth pass.
.animate
        lda.w !EnFrame                  ; $7BCC
        and.b #$03
        bne +                           ; $7BD0 `RET NZ`
        lda.w !Slots+!EN_SPRITE,x       ; $7BD4
        eor.b #!LARVA_ANIM_XOR
        sta.w !Slots+!EN_SPRITE,x
+       rts

; ---------------------------------------------------------------------------
; 02:$7CDD `metroid_correctPosition`: after a seek step, a wall on the side
; each half of the vector points at puts that axis back where the pass began.
; Down and right ask only the probe; up and left also refuse to go above or
; left of $10. The larvae's; the baby has its own, which eats blocks.
;
; in: X = slot offset.
; ---------------------------------------------------------------------------
MetroidCorrectPosition:
        sep #$20
        lda.w !Slots+!EN_COUNTER,x      ; $7CDD
        cmp.b #!LARVA_VEC0              ; $7CDF `CP $10`
        bcc .up                         ; $7CE1
        %call0(EnCollideDownFarWide)    ; $7CE3 `CALL $4B17`
        sep #$20
        lda.w !EnBgResult               ; $7CE6
        and.b #$02                      ; $7CE9 `BIT 1,A`
        beq .x                          ; $7CEB
.revertY
        lda.w !EnYMirror                ; $7CED
        sta.w !Slots+!EN_YPOS,x
        bra .x
.up
        lda.w !Slots+!EN_YPOS,x         ; $7CF4
        cmp.b #!LARVA_EDGE              ; $7CF6
        bcc .revertY                    ; $7CF8
        %call0(EnCollideUpFarWide)      ; $7CFA `CALL $4D04`
        sep #$20
        lda.w !EnBgResult               ; $7CFD
        and.b #$08                      ; $7D00 `BIT 3,A`
        bne .revertY                    ; $7D02
.x
        lda.w !Slots+!EN_STATE,x        ; $7D04
        cmp.b #!LARVA_VEC0              ; $7D06
        bcc .left                       ; $7D08
        %call0(EnCollideRightFarWide)   ; $7D0A `CALL $4736`
        sep #$20
        lda.w !EnBgResult               ; $7D0D
        and.b #$01                      ; $7D10 `BIT 0,A`
        beq .done                       ; $7D12 `RET Z`
.revertX
        lda.w !EnXMirror                ; $7D13
        sta.w !Slots+!EN_XPOS,x
.done
        rts
.left
        lda.w !Slots+!EN_XPOS,x         ; $7D19
        cmp.b #!LARVA_EDGE              ; $7D1B
        bcc .revertX                    ; $7D1D
        %call0(EnCollideLeftFarWide)    ; $7D1F `CALL $490F`
        sep #$20
        lda.w !EnBgResult               ; $7D22
        and.b #$04                      ; $7D25 `BIT 2,A`
        bne .revertX                    ; $7D27
        rts

; ---------------------------------------------------------------------------
; 1.0 Step 17: 02:$6B83 `enAI_metroidStinger`, the final area's event: no
; sprite, one record ($E:$22, #43). On its first pass it adds the eight larvae
; to the shown count, sets the shuffle timer, asks for the hive's song and
; freezes Samus; on its $8A'th it deletes itself, its flag dead, and thaws her.
; Its flag is saved, so it runs once a game.
;
; in: X = slot offset.
; ---------------------------------------------------------------------------
EnAiStinger:
        sep #$20
        rep #$10
        inc.w !Slots+!EN_COUNTER,x      ; $6B86
        lda.w !Slots+!EN_COUNTER,x
        cmp.b #!STINGER_END             ; $6B88
        beq .end                        ; $6B8A
        dec a
        bne .out                        ; $6B8D `RET NZ`: only the first pass
        sed
        clc
        lda.w !MetDisp                  ; $6B91
.larvae                                 ; `stinger`'s behaviour fault
        adc.b #!STINGER_LARVAE          ; $6B92 `ADD A,$08 / DAA`
        sta.w !MetDisp
        cld
        lda.b #!STINGER_SHUFFLE         ; $6B96
        sta.w !Shuffle
        lda.b #!SONG_HIVE               ; $6B9B
        sta.w !MetSong
        %audio_put_long(!REQ_SONG, $026B9D)
        lda.b #$01                      ; $6BA0
        sta.w !Cutscene
.out
        rep #$30
        rts
.end
        jsl EnemyDeleteSelfLong         ; $6BA6 `CALL $3CA6`
        sep #$20
        lda.b #!FLAG_DEAD               ; $6BA9
        sta.w !Slots+!EN_FLAG,x
        stz.w !Cutscene                 ; $6BAE
        bra .out

; ---------------------------------------------------------------------------
; 1.0 Step 21: 02:$7BE5 `enAI_babyMetroid`, the egg the Queen's death leaves at
; `$F:$A7` (#42), and the baby that hatches from it and follows Samus to her
; ship, eating the blocks in its way.
;
; Its state is `metroid_state`, as a Metroid fight's is, and the fight flag is
; raised for it too. **0, the egg**: it blinks, and with Samus within $18 across
; and $10 down it freezes her and wiggles for $30 passes, then bursts (3) and
; rises (1) for $0C passes each, and thaws her. A baby whose spawn flag is
; already `$04`, met again, is no egg: it waits for her within $60 across and
; follows. **2, following**: the Zeta's chase, then `baby_checkBlocks`, then
; kept on the screen -- low as well as high, where the Zeta's is not.
;
; Nothing hurts it: it never asks what touched it.
;
; in: X = slot offset.
; ---------------------------------------------------------------------------
EnAiBaby:
        sep #$20
        rep #$10
        lda.w !MetState                 ; $7BE5
        beq .egg                        ; $7BE9 `JR Z,$7C20`
        dec a
        bne +                           ; $7BEC `JR Z,$7C04`
        jmp .rise
+       dec a
        beq +                           ; $7BEF `JP NZ`, "the sneaky nz"
        jmp .burst
+       lda.w !EnFrame                  ; $7BF2 `CALL $6B3A`, `enemy_flipSpriteId.fourFrame`
        and.b #$03
        bne +
        lda.w !Slots+!EN_SPRITE,x
        eor.b #$01
        sta.w !Slots+!EN_SPRITE,x
+       lda.b #!SEEK_STEP               ; $7BF5 `LD B,$02`
        sta.w !MetB
        lda.b #!SEEK_MAX                ; $7BF7 `LD DE,$2000`
        sta.w !MetD
        lda.b #!SEEK_MIN
        sta.w !MetE
        jsr EnemySeekSamus              ; $7BFA `CALL $3CBA`, `enemy_seekSamus`'s far call
        jsr BabyCheckBlocks             ; $7BFD `CALL $7D2A`
        jsr BabyKeepOnscreen            ; $7C00 `CALL $7DDC`
.out
        rep #$30
        rts

; $7C04 `.case_1`: rising out of the egg, swaying, $0C passes; then the chase's
; vector at rest, state 2, and Samus thawed.
.rise
        jsr MetroidOscillateWide        ; $7C04 `CALL $75FF`
        sep #$20
        dec.w !Slots+!EN_YPOS,x         ; $7C07
        inc.w !Slots+!EN_COUNTER,x      ; $7C0B
        lda.w !Slots+!EN_COUNTER,x
        cmp.b #!BABY_RISE_N             ; $7C10
        bne .out                        ; $7C12 `RET NZ`
        lda.b #!BABY_VEC0               ; $7C13
        sta.w !Slots+!EN_COUNTER,x
        sta.w !Slots+!EN_STATE,x        ; $7C16
        inc.w !MetState                 ; $7C17
        stz.w !Cutscene                 ; $7C1B
        bra .out

; $7C20 `.case_0`.
.egg
        lda.w !Slots+!EN_FLAG,x         ; $7C20
        cmp.b #!FLAG_ACTIVE_SEEN        ; $7C22 `CP $04`
        bne +
        jmp .seen                       ; $7C24 `JR Z,$7C6B`
+       lda.w !EnFrame                  ; $7C26 `CALL $7CAF`, `.animateFlash`
        and.b #$03
        bne +                           ; $7CB3 `RET NZ`
        lda.w !Slots+!EN_STUN,x         ; $7CB4
        eor.b #!BABY_FLASH
        sta.w !Slots+!EN_STUN,x
+       lda.w !OnscreenX                ; $7C2C
        sec
        sbc.w !Slots+!EN_XPOS,x         ; $7C2F `SUB (HL)`
        bcs +                           ; $7C30 `JR NC`
        eor.b #$FF                      ; $7C32 `CPL`
        inc a
+
.nearTest                               ; `baby`'s behaviour fault
        cmp.b #!BABY_NEAR_X             ; $7C34
        bcs .out                        ; $7C36 `RET NC`
        lda.w !OnscreenY                ; $7C38
        sec
        sbc.w !Slots+!EN_YPOS,x         ; $7C3B
        bcs +                           ; $7C3C
        eor.b #$FF                      ; $7C3E
        inc a
+       cmp.b #!BABY_NEAR_Y             ; $7C40
        bcs .out                        ; $7C42 `RET NC`
        lda.b #$01                      ; $7C43
        sta.w !Cutscene
        jsr .wiggle                     ; $7C48 `CALL $7CBC`
        inc.w !Slots+!EN_STATE,x        ; $7C4E
        lda.w !Slots+!EN_STATE,x
        cmp.b #!BABY_WIGGLE_N           ; $7C50
        bne .out                        ; $7C52 `RET NZ`
        stz.w !Slots+!EN_STATE,x        ; $7C54
        stz.w !Slots+!EN_COUNTER,x      ; $7C55
        stz.w !Slots+!EN_STUN,x         ; $7C56: no longer blinking
        lda.b #!BABY_STATE_EGG          ; $7C58
        sta.w !MetState
        inc.w !MetFight                 ; $7C60
        lda.b #!FLAG_ACTIVE_SEEN        ; $7C61
        sta.w !Slots+!EN_FLAG,x
.cry
        lda.b #!NOISE_BABY_BLOCK        ; $7C65 and $7C87
        sta.w !SfxNoise
        %audio_put_long(!REQ_SFX_NOISE, $027C67, $027C89)
        jmp .out

; $7C6B `.else_A`: hatched before, and met again.
.seen
        lda.b #!SPR_BABY                ; $7C6B
        sta.w !Slots+!EN_SPRITE,x
        lda.w !OnscreenX                ; $7C72
        sec
        sbc.w !Slots+!EN_XPOS,x         ; $7C75
        bcs +                           ; $7C76
        eor.b #$FF
        inc a
+       cmp.b #!BABY_SEEN_X             ; $7C7A
        bcc +
        jmp .out                        ; $7C7C `RET NC`
+       lda.b #$01                      ; $7C7D
        sta.w !MetFight
        lda.b #!BABY_STATE_ACTIVE       ; $7C82
        sta.w !MetState
        bra .cry

; $7C8D `.case_3`: the egg bursts. Odd passes show the explosion's frames,
; even ones the baby; on the $0C'th it starts to rise.
.burst
        inc.w !Slots+!EN_COUNTER,x      ; $7C90
        lda.w !Slots+!EN_COUNTER,x
        bit.b #$01                      ; $7C92 `BIT 0,A`
        beq +                           ; $7C94
        lsr a                           ; $7C96
        clc
        adc.b #!SPR_EXP_BIG             ; $7C98 `ADD A,$E2`
        sta.w !Slots+!EN_SPRITE,x
        jmp .out
+       cmp.b #!BABY_BURST_N            ; $7C9D
        bne +                           ; $7C9F `CALL Z,$7CA7`
        stz.w !Slots+!EN_COUNTER,x      ; $7CA7 `.prepState1`
        lda.b #$01                      ; $7CA9
        sta.w !MetState
+       lda.b #!SPR_BABY                ; $7CA2
        sta.w !Slots+!EN_SPRITE,x
        jmp .out

; $7CBC `.animateEggWiggle`: on even passes the egg's sprite steps between $A5
; and $A7, the way `+$09`'s low bit says, turning at either end.
.wiggle
        lda.w !EnFrame                  ; $7CBC
        and.b #$01
        bne .wiggleOut                  ; $7CC0 `RET NZ`
        lda.w !Slots+!EN_COUNTER,x      ; $7CC4
        dec a
        beq .down                       ; $7CC7
        inc.w !Slots+!EN_SPRITE,x       ; $7CC9
        lda.w !Slots+!EN_SPRITE,x
        cmp.b #!SPR_EGG_3               ; $7CCB
        bne .wiggleOut                  ; $7CCD `RET NZ`
.turn
        lda.w !Slots+!EN_COUNTER,x      ; $7CCE
        eor.b #$01
        sta.w !Slots+!EN_COUNTER,x
.wiggleOut
        rts
.down
        dec.w !Slots+!EN_SPRITE,x       ; $7CD6
        lda.w !Slots+!EN_SPRITE,x
        cmp.b #!SPR_EGG_1               ; $7CD8
        bne .wiggleOut                  ; $7CDA `RET NZ`
        bra .turn                       ; $7CDB

; ---------------------------------------------------------------------------
; 02:$7D2A `baby_checkBlocks`: `metroid_correctPosition` with the mid probes,
; Y probed at the X the pass began with, and a probe that meets its block --
; tile $64, `metroid_babyTouchingTile` -- eats it before putting the axis back.
; The eaten tile is the probe's last point, so `DestroyBlock` takes its
; `!TileY`/`!TileX` as the original's `destroyBlock` takes `tileY`/`tileX`.
;
; in: X = slot offset.
; ---------------------------------------------------------------------------
BabyCheckBlocks:
        sep #$20
        lda.w !Slots+!EN_XPOS,x         ; $7D2A
        sta.w !BabyTempX                ; $7D2E
        lda.w !EnXMirror                ; $7D31
        sta.w !Slots+!EN_XPOS,x         ; $7D34
        lda.w !Slots+!EN_COUNTER,x      ; $7D35
        cmp.b #!BABY_VEC0               ; $7D37 `CP $10`
        bcc .up                         ; $7D39
        %call0(EnCollideDownMid)        ; $7D3B `CALL $4A28`
        sep #$20
        lda.w !EnBgResult               ; $7D3E
        and.b #$02                      ; $7D41 `BIT 1,A`
        beq .x                          ; $7D43
.eatY
        lda.w !BabyTile                 ; $7D45
        cmp.b #!BABY_TILE               ; $7D48
        bne .revertY                    ; $7D4A `CALL Z,$7D97`
        jsr BabyClearBlock
.revertY
        lda.w !EnYMirror                ; $7D4D
        sta.w !Slots+!EN_YPOS,x
        bra .x
.up
        lda.w !Slots+!EN_YPOS,x         ; $7D54
        cmp.b #$10                      ; $7D56
        bcc .revertY                    ; $7D58
        %call0(EnCollideUpMid)          ; $7D5A `CALL $4C30`
        sep #$20
        lda.w !EnBgResult               ; $7D5D
        and.b #$08                      ; $7D60 `BIT 3,A`
        bne .eatY                       ; $7D62
.x
        lda.w !BabyTempX                ; $7D64
        sta.w !Slots+!EN_XPOS,x         ; $7D67
        lda.w !Slots+!EN_STATE,x        ; $7D69
        cmp.b #!BABY_VEC0               ; $7D6B
        bcc .left                       ; $7D6D
        jsr EnCollideRightMid           ; $7D6F `CALL $4662`
        lda.w !EnBgResult               ; $7D72
        and.b #$01                      ; $7D75 `BIT 0,A`
        beq .done                       ; $7D77 `RET Z`
.eatX
        lda.w !BabyTile                 ; $7D78
        cmp.b #!BABY_TILE               ; $7D7B
        bne .revertX                    ; $7D7D `CALL Z,$7D97`
        jsr BabyClearBlock
.revertX
        lda.w !EnXMirror                ; $7D80
        sta.w !Slots+!EN_XPOS,x
.done
        rts
.left
        lda.w !Slots+!EN_XPOS,x         ; $7D86
        cmp.b #$10                      ; $7D88
        bcc .revertX                    ; $7D8A
        jsr EnCollideLeftMid            ; $7D8C `CALL $483B`
        lda.w !EnBgResult               ; $7D8F
        and.b #$04                      ; $7D92 `BIT 2,A`
        bne .eatX                       ; $7D94
        rts

; 02:$7D97 `baby_clearBlock`: the block is gone, and the baby's cry over the
; shot block's noise.
BabyClearBlock:
        phx
        %call0(DestroyBlock)            ; $7D97 `CALL $3CCE`, `destroyBlock`'s far call
        sep #$20
        rep #$10
        plx
        lda.b #!NOISE_BABY_BLOCK        ; $7D9A
        sta.w !SfxNoise
        %audio_put_long(!REQ_SFX_NOISE, $027D9C)
        rts

; ---------------------------------------------------------------------------
; 02:$7DDC `baby_keepOnscreen`: Y and X both held between $18 and $90.
; ---------------------------------------------------------------------------
BabyKeepOnscreen:
        sep #$20
        lda.w !Slots+!EN_YPOS,x         ; $7DE2
        cmp.b #!KEEP_LO                 ; $7DE3 `CP B`
        bcs +                           ; $7DE4
        lda.b #!KEEP_LO                 ; $7DE6 `LD (HL),B`
        sta.w !Slots+!EN_YPOS,x
        bra ++                          ; $7DE7
+       cmp.b #!KEEP_HI                 ; $7DE9 `CP C`
        bcc ++                          ; $7DEA
        lda.b #!KEEP_HI                 ; $7DEC
        sta.w !Slots+!EN_YPOS,x
++      lda.w !Slots+!EN_XPOS,x         ; $7DEE
        cmp.b #!KEEP_LO                 ; $7DEF
        bcs +                           ; $7DF0
        lda.b #!KEEP_LO                 ; $7DF2
        sta.w !Slots+!EN_XPOS,x
        rts
+       cmp.b #!KEEP_HI                 ; $7DF4
        bcc +                           ; $7DF5 `RET C`
        lda.b #!KEEP_HI                 ; $7DF6
        sta.w !Slots+!EN_XPOS,x
+       rts

; 00:$36BB, `queen_roomFlag` cleared before the LCD goes off. While `!RoomMode`
; is $11, `QueenPass` builds her bands on every pass and `QueenNmi` arms them on
; every vblank, so `QueenOff` alone lasted only until the GAME OVER screen's
; first frame (1.0 Step 25). Its own routine so the `queen` rung's `still` case
; can take it out.
GameOverQueenFlag:
        sep #$20
        stz !RoomMode
        rts

; 00:$36BD-$36F4, on the frame the noise is found spent: the LCD off, both
; tilemaps cleared, OAM cleared, the title's characters copied, and the text.
; Everything goes up at once under forced blank; `!DeathBlank` is the frames the
; Game Boy spends doing it, and NMI touches no video while it counts, so nothing
; in NMI shares these DMA registers.
;
; In bank 1 since 1.0 Step 22, for bank 0's room; its bank-0 calls are
; `%call0`s.
GameOverScreen:
        %call0(AudioNoImplicit) ; the loop's test ended it: no call this frame
        sep #$20
        lda.b #!GAME_OVER_BLANK
        sta.w !DeathBlank
        jsr GameOverQueenFlag   ; $36BB
        jsl QueenOff            ; 1.0 Step 19c: her INIDISP channel first
        sep #$20
        lda.b #$80
        sta !INIDISP
        rep #$30
        %call0(InitOam)         ; $36C7 `hOamBufferIndex` and $36CA `clearAllOam`
        %call0(UploadTitleChr)  ; $36CD-$36E4
        ; $36C4 `clearTilemaps`, through the title's rotation: the id's
        ; character is id + $80, palette and priority zero.
        rep #$30
        ldx.w #$0000
        lda.w #(!GAME_OVER_CLEAR+$80)&$FF
-       sta.w !TilemapBuf,x
        inx
        inx
        cpx.w #!TilemapBytes
        bne -
        ; $36E6, until the $80.
        sep #$20
        %tabp(!GameOverTextA)
        ldx.w #((!GAME_OVER_ROW*32)+!GAME_OVER_COL)*2
        ldy.w #$0000
-       lda [!TabP],y
        cmp.b #!GAME_OVER_END
        beq +
        clc
        adc.b #$80
        sta.w !TilemapBuf,x
        stz.w !TilemapBuf+1,x
        inx
        inx
        iny
        bra -
+       rep #$30
        %call0(UploadTilemap)
        ; $36F5 scroll zero: the title's camera, which is scroll zero through
        ; `WriteScroll`'s biases. NMI writes it once the blank is over. The
        ; clamp and not one past it, as the title's (Step 24h).
        lda.w #!CAM_MIN_X
        sta !CamX
        lda.w #!CAM_MIN_Y
        sta !CamY
        ; $3700 `LD A,$C3`: the window off, so BG3 on its lines.
        sep #$20
        lda.w !BAND_PLAY_TM
        sta.w !BAND_HUD_TM
        rep #$30
        jml MainLoop


; ===========================================================================
; 1.0 Step 22 (C7): the ending. Game mode $12, `prepareCredits` (05:$587F),
; fades the room out and sets the credits up; mode $13, `creditsRoutine`
; (05:$55A3), rolls them while Samus plays one of four endings beside them, by
; `gameTimeHours`. Nothing leaves mode $13 but the soft reset: the credits hold
; their last screen without end, and `credits_rebootGame` (05:$5985) is reached
; by nothing. `src/credits.zig` measures our Game Boy's ending; the `credits`
; rung grades the cart against it.
; ===========================================================================

; Every frame, from `MainLoop`'s top: the soft reset, then the readout.
FrameTop:
        jsr SoftReset
        jmp Readout

; 00:$02E1. `mainGameLoop` reboots when A, B, Start and Select are all held,
; in every mode it runs (`CP $0F` on the held byte, a mask's equality, so
; anything held with them still reboots). The Game Boy tests it at the end of
; the pass, after the mode's handler; the port tests the same pad at the
; pass's top, so the pass it reboots on does nothing first. 0b's B7 left it
; out. Any widths in; returns 8-bit A when it does not reboot.
SoftReset:
        rep #$20
        lda !InputPressed
        and.w #!SOFT_RESET
.mask                                   ; the `credits` rung's fault patches this
        cmp.w #!SOFT_RESET
        sep #$20
        bne +
        jml Reboot              ; `JP Z,$01FB`, `bootRoutine`
+       rts

; From `DeathFrame` with 8-bit A holding `!DeathMode`, $12 or $13: one pass of
; `mainGameLoop` with that mode. The pass's own `handleAudio` is the main
; loop's implicit one; the door script has nothing to run; `waitForNextFrame`
; zeroes the OAM index (00:$0431), which is this pass's first act here.
CreditsFrame:
        rep #$30
        stz !OamIdx
        sep #$20
        cmp.b #!MODE_CREDITS
        beq +
        jsr PrepareCredits
        rep #$30
        jml MainLoop
+       jsr CreditsRoutine
        rep #$30
        jml MainLoop

; ---------------------------------------------------------------------------
; 05:$587F `prepareCredits`. While `countdownTimerLow` runs, the fade: the
; palette is `credits_paletteFade[countdown >> 5]`, read from the end of the
; table to its start, into `bg_palette` and both object palettes -- one INIDISP
; here, as everywhere (`ApplyPalette`). Under $0E the countdown is cleared and
; the low health beep with it, and the same pass sets the credits up.
; ---------------------------------------------------------------------------
PrepareCredits:
        sep #$20
        rep #$10
        lda !Countdown                  ; $5882, the low byte
        beq CreditsSetup                ; $5886
.fadeIndex                              ; the `credits` rung's fault patches this
        and.b #$F0                      ; $5888 `AND $F0 / SWAP A / SRL A`
        lsr a
        lsr a
        lsr a
        lsr a
        lsr a
        rep #$20
        and.w #$00FF
        tay
        sep #$20
        %tabp(!CrFadeA)                 ; $587F `LD HL,$5877`
        lda [!TabP],y                   ; $5892
        sta.w !BgPalette                ; $5893, and $5896 and $5899 the objects'
        jsl PaletteBrightness           ; `ApplyPalette`, long
        sta !INIDISP
        lda !Countdown                  ; $589C
        cmp.b #!CREDITS_FADE_END        ; $589F `CP $0E / RET NC`
        bcc +
        rts
+       stz !Countdown                  ; $58A2, the low byte
        lda.b #$FF                      ; $58A6: the low health beep, cleared
        %audio_put_long(!REQ_SFX_WAVE, $0558A8)
        stz.w !BeepAsked
        ; fall into the setup

; 05:$58AB. The LCD off: no vblank at all on the Game Boy until it is back on,
; so no NMI here -- the frame counter and the countdown stand still as the
; Game Boy's do, and the pass takes the Game Boy's frames (`!CREDITS_SETUP`,
; measured by `src/credits.zig`) before the next begins. Everything goes up
; under forced blank with nothing in NMI to share the DMA registers.
CreditsSetup:
        sep #$20
        rep #$10
        stz !NMITIMEN                   ; $58AB `LD A,$03 / LDH (rLCDC),A`
        lda.b #$80
        sta !INIDISP
        jsl QueenOff                    ; her channels, as the GAME OVER screen's
        sep #$20
        rep #$10
        ; $58AF-$58BB: `bg_palette` $93; the objects' $93 and $43 have no port
        ; state (`PutObject`'s palettes are fixed) and no credits object reads
        ; OBP1.
        lda.b #!PALETTE_NORMAL
        sta.w !BgPalette
        ; $58BE `clearTilemaps`: $FF everywhere, through the signed window's
        ; rotation, behind the objects' priority as the play field's words
        ; are. The window's map, BG2's, is off with the window (`$C3`).
        rep #$30
        ldx.w #$0000
        lda.w #((!CREDITS_BLANK_ID+$80)&$FF)|!PLAY_PRI
-       sta.w !TilemapBuf,x
        inx
        inx
        cpx.w #!TilemapBytes
        bne -
        %call0(UploadTilemap)
        ; $58C1-$58CF, the OAM buffer: every object parked.
        %call0(InitOam)
        ; $58D1-$58F5: the characters, `CreditsChrRows` in the Game Boy's
        ; order. `credits_loadFont` (05:$4030) first.
        ldx.w #$0000
-       phx
        jsr CreditsChrRow
        plx
        txa
        clc
        adc.w #!CR_CHR_ROW
        tax
        cpx.w #CreditsChrRowsEnd-CreditsChrRows
        bne -
        ; $58F8-$5903: the text pointer, and `credits_unusedVar`, which
        ; nothing reads and the port does not keep.
        lda.w #!CREDITS_TEXT_BUF
        sta.w !CrTextP
        ; $5906-$5912: sixteen bytes of the stars' thirty-two, `LD B,$10`.
        ; The other eight stars are what `bootRoutine`'s clear left, zero:
        ; nothing else writes them, and they drop in from the top.
        sep #$20
        %tabp(!CrStarsA)
        ldy.w #$0000
-       lda [!TabP],y
        sta.w !CrStars,y
        iny
        cpy.w #!CREDITS_STAR_COPY
        bne -
        ; $5914 `loadCreditsText` (00:$3C6A): into cart RAM, to and with $F0.
        %tabp(!CrTextA)
        ldy.w #$0000
        ldx.w #!CREDITS_TEXT_BUF
-       lda [!TabP],y
        sta.l !SRAM-$A000,x
        inx
        iny
        cmp.b #!CREDITS_END
        bne -
        ; $5917-$591B: both scrolls zero, the title's camera; the window off
        ; ($591E `LD A,$C3`), so BG3 on its lines.
        stz.w !CrScrollY
        rep #$20
        lda.w #!CAM_MIN_X
        sta !CamX
        lda.w #!CAM_MIN_Y
        sta !CamY
        sep #$20
        lda.w !BAND_PLAY_TM
        sta.w !BAND_HUD_TM
        ; The Game Boy's LCD-off frames, but the one this pass ends on.
        ldx.w #!CREDITS_SETUP-1
.vblank
        lda !HVBJOY
        bpl .vblank                     ; a vblank begun
-       lda !HVBJOY
        bmi -                           ; and ended
        dex
        bne .vblank
        ; $591E: the LCD on. NMI back in active display, never in vblank,
        ; for `Reset`'s reason.
        lda !RDNMI
        lda.w !BgPalette
        jsl PaletteBrightness
        sta !INIDISP
        lda.b #$81
        sta !NMITIMEN
        lda.b #$FF                      ; $5922, the low byte
        sta !Countdown
        lda.b #!CREDITS_SAMUS_Y         ; $5927
        sta.w !CrSamusY
        lda.b #!CREDITS_SAMUS_X         ; $592B
        sta.w !CrSamusX
        lda.b #!CREDITS_SONG            ; $592F
        %audio_put_long(!REQ_SONG, $055931)
        stz.w !CrState                  ; $5934
        lda.b #!MODE_CREDITS            ; $5938 `INC A`
        sta.w !DeathMode
        rts

; One of `CreditsChrRows`, X its offset: a sheet's span to VRAM, by DMA.
CreditsChrRow:
        sep #$20
        lda.l CreditsChrRows,x          ; which of `CreditsChr`'s ids
        phx
        rep #$20
        and.w #$00FF
        tax
        sep #$20
        lda.l CreditsChr,x
        sta !ArgId
        plx
        lda.l CreditsChrRows+1,x        ; its class
        sta !ArgClass
        phx
        rep #$30
        jsl FindBlobLong
        bcs +
        jml Fatal
+       plx
        sep #$20
        lda.b #$80
        sta !VMAIN
        rep #$20
        lda.l CreditsChrRows+4,x
        sta !VMADDL
        lda.l CreditsChrRows+2,x        ; the span's first byte in the blob
        clc
        adc !Blob
        sta !A1T0L
        sep #$20
        lda !Blob+2
        adc.b #$00
        sta !A1B0
        lda.b #$01
        sta !DMAP0
        lda.b #$18
        sta !BBAD0
        rep #$20
        lda.l CreditsChrRows+6,x
        sta !DAS0L
        sep #$20
        lda.b #$01
        sta !MDMAEN
        rep #$30
        rts

; The ids of the credits' sheets, by `snes_inject` from their names: the
; objects' two, then the background's four. $FF here.
CreditsChr:
        fillbyte $FF : fill !CREDITS_CHR_N

; Each copy `prepareCredits` makes, as the cart's VRAM holds it: which
; `CreditsChr` id, its class, the span's first byte in the converted sheet, the
; VRAM word, and the bytes. The background's characters are the signed
; window's, a Game Boy id `n` at character `n + $80` (`charForTitleId`), so a
; Game Boy address `a` in $8800-$97FF is BG3 word `(a - $8800) / 2`; the
; objects' are 4bpp, sixteen words a tile from `!OBJ_CHAR_BASE`.
CreditsChrRows:
        ; 05:$4030 `credits_loadFont`: $200 of the font's $300 to $9200.
        db 5, !CLASS_CHR_BG : dw $0000, ($9200-$8800)/2, $0200
        ; 05:$58D4: $1000 from `gfx_creditsSprTiles` to $8000, which reads
        ; past its $F00 into `gfx_theEnd`; those $100 land at $8F00, under
        ; the numbers' copy below, and are not uploaded. The objects' tiles
        ; $00-$EF, and the background's half of them, $8800-$8EFF.
        db 0, !CLASS_CHR_OBJ : dw $0000, !OBJ_CHAR_BASE, $F0*32
        db 2, !CLASS_CHR_BG : dw $0800, $0000, $0700
        ; 05:$58E0: `gfx_theEnd` to $9000.
        db 4, !CLASS_CHR_BG : dw $0000, ($9000-$8800)/2, $0100
        ; 05:$58EC: `gfx_creditsNumbers` to $8F00, objects $F0-$FF and the
        ; background's id $FF, the blank every row is cleared to.
        db 1, !CLASS_CHR_OBJ : dw $0000, !OBJ_CHAR_BASE+($F0*16), $10*32
        db 3, !CLASS_CHR_BG : dw $0000, ($8F00-$8800)/2, $0100
CreditsChrRowsEnd:

; ---------------------------------------------------------------------------
; 05:$55A3 `creditsRoutine`: Samus, the scroll, the clock, the stars, and the
; rest of the buffer parked.
; ---------------------------------------------------------------------------
CreditsRoutine:
        sep #$20
        rep #$10
        lda.w !CrSamusY                 ; $55A3
        sta !SprY
        lda.w !CrSamusX
        sta !SprX
        jsr CreditsAnimateSamus         ; $55AB
        jsr CreditsScroll               ; $55AE
        jsr CreditsDrawTimer            ; $55B1
        jsr CreditsMoveStars            ; $55B4
        jsr CreditsDrawStars            ; $55B7
        jsr CreditsOamLimit
        jsl ClearUnusedOamLong          ; $55BA, `title_clearUnusedOamSlots`
        ; `scrollY` into the picture: the camera that makes it, as the title's
        ; makes zero (NMI writes it).
        rep #$20
        lda.w !CrScrollY
        and.w #$00FF
        clc
        adc.w #!CAM_MIN_Y
        sta !CamY
        rts

; The Game Boy's OAM buffer is forty objects ($C000-$C09F), and neither
; `drawNonGameSprite` nor `credits_drawOneDigit` stops at its end: past it a
; part goes to $C0A0 on, which nothing reads (unused to $C1FF), and
; `title_clearUnusedOamSlots` clears nothing there. In the suit Samus is 36
; parts, so four stars show and twelve do not. The cart's shadow holds 128:
; what the Game Boy put past its forty is parked, and the index stays where
; the Game Boy's is.
CreditsOamLimit:
        rep #$30
        ldx.w #!GB_OAM_BYTES
-       cpx !OamIdx
        bcs +
        sep #$20
        lda.b #!OAM_HIDDEN_Y
        sta.w !OamBuf+1,x
        rep #$20
        txa
        clc
        adc.w #$0004
        tax
        bra -
+       rts

; 05:$593E `credits_scrollHandler`. At the $F0 the scroll is done; otherwise a
; pixel every fourth frame, and on each eighth the row just under the screen
; (`tileY` = scroll + $A0, `getTilemapAddress`) is NMI's to draw.
CreditsScroll:
        sep #$20
        rep #$10
        ldx.w !CrTextP                  ; $593E-$5945
        lda.l !SRAM-$A000,x             ; $594B
        cmp.b #!CREDITS_END             ; $5953
        bne +
        lda.b #$01                      ; $5957
        sta.w !CrDone
        rts
+       lda !FrameCount                 ; $595D
.rate                                   ; the `credits` rung's fault patches this
        and.b #$03
        bne .out
        lda.w !CrScrollY                ; $5962
        inc a
        sta.w !CrScrollY
        and.b #$07                      ; $596C
        bne .out
        ; $596F-$597C, `getTilemapAddress` (00:$22BC): tileY less $10,
        ; eighths, rows of $20 from $9800; tileX $08 is column zero.
        lda.w !CrScrollY
        clc
        adc.b #!CREDITS_ROW_Y
        sec
        sbc.b #$10
        lsr a
        lsr a
        lsr a
        rep #$20
        and.w #$00FF
        asl a
        asl a
        asl a
        asl a
        asl a
        clc
        adc.w #$9800
        sta.w !CrTileDest
        sep #$20
        lda.b #$FF                      ; $597F
        sta.w !CrLineDue
.out
        rts

; NMI's half, 05:$403D `VBlank_drawCreditsLine`: twenty characters less $21
; at the row, or a blank row for $F1 (one byte), and the pointer kept. On the
; Game Boy it replaces the rest of the vblank handler; here what it would
; skip is the status bar's (BG2, off with the window) and nothing visible.
; From `HudBaseNmi`, any widths.
CreditsLineNmi:
        php
        sep #$20
        lda.w !CrLineDue
        beq .done
        lda.b #$80
        sta !VMAIN
        rep #$30
        lda.w !CrTileDest
        sec
        sbc.w #$9800
        clc
        adc.w #!BG3_MAP
        sta !VMADDL
        ldx.w !CrTextP
        ldy.w #!CREDITS_LINE
        sep #$20
        lda.l !SRAM-$A000,x             ; $4059 `CP $F1`
        cmp.b #!CREDITS_BLANK_LINE
        beq .blank
-       lda.l !SRAM-$A000,x             ; $405F
        inx
        sec
        sbc.b #!CREDITS_CHAR_BIAS       ; $4060 `SUB $21`
        clc
        adc.b #$80                      ; the signed window's rotation
        sta !VMDATAL
        lda.b #!PLAY_PRI>>8
        sta !VMDATAH
        dey
        bne -
        bra .kept
.blank
        lda.b #(!CREDITS_BLANK_ID+$80)&$FF      ; $406C `LD A,$FF`
        sta !VMDATAL
        lda.b #!PLAY_PRI>>8
        sta !VMDATAH
        dey
        bne .blank
        inx                             ; $4075
.kept
        rep #$20
        txa
        sta.w !CrTextP
        sep #$20
        stz.w !CrLineDue                ; $4081
.done
        plp
        rts

; 05:$55BE `credits_drawTimer`: once the scroll is done, the hours and the
; minutes at ($88, $42) and ($88, $56).
CreditsDrawTimer:
        sep #$20
        lda.w !CrDone
        beq .out
        lda.b #$88                      ; $55C3
        sta !SprY
        lda.b #$42
        sta !SprX
        lda.w !IgtHours                 ; $55CB
        jsr CreditsTimerDigits
        lda.b #$56                      ; $55D1
        sta !SprX
        lda.w !IgtMinutes
        jsr CreditsTimerDigits
.out
        rts

; 05:$4000 `credits_drawTimerDigits`: A's two BCD digits as objects $F0-$F9.
CreditsTimerDigits:
        pha
        lsr a
        lsr a
        lsr a
        lsr a
        clc
        adc.b #$F0
        jsr CreditsDigit
        pla
        and.b #$0F
        clc
        adc.b #$F0
        ; fall through
; 05:$4015 `credits_drawOneDigit`: one object at the sprite position, with
; `hSpriteAttr` as it stands (not XORed), and the X on by eight.
CreditsDigit:
        sta.w !ObjTile
        lda !SprY
        sta.w !ObjY
        lda !SprX
        sta.w !ObjX
        clc
        adc.b #$08
        sta !SprX
        lda.w !SprAttr
        sta.w !ObjAttr
        rep #$30
        jsl PutObjectLong
        sep #$20
        rep #$10
        rts

; 05:$55DC `credits_moveStars`: all sixteen down a pixel every fourth frame,
; back to $10 at $A0; left a pixel every frame, back to $A8 past the edge.
CreditsMoveStars:
        sep #$20
        rep #$10
        ldx.w #$0000
.star
        lda !FrameCount                 ; $55E1
        and.b #$03
        bne +
        lda.w !CrStars,x                ; $55E7
        inc a
        sta.w !CrStars,x
        cmp.b #$A0                      ; $55EB
        bcc +
        lda.b #$10
        sta.w !CrStars,x
+       lda.w !CrStars+1,x              ; $55F3
        dec a
        sta.w !CrStars+1,x
        cmp.b #$F8                      ; $55F7
        bcc +
        lda.b #$A8
        sta.w !CrStars+1,x
+       inx
        inx
        cpx.w #!CREDITS_STARS*2
        bne .star
        rts

; 05:$5603 `credits_drawStars`: each star at its place, sprite $1B or $1C by
; the low bit of the loop's count, which runs from 16 down.
CreditsDrawStars:
        sep #$20
        rep #$10
        ldx.w #$0000
.star
        lda.w !CrStars,x                ; $5608
        sta !SprY
        lda.w !CrStars+1,x
        sta !SprX
        txa                             ; B is 16 less the star, so its low
        lsr a                           ;   bit is the star's own
        and.b #$01                      ; $560E `AND $01`
        clc
        adc.b #!SPR_CREDITS_STAR
        sta !SpriteId
        phx
        jsr DrawNonGameSprite           ; $5617
        plx
        sep #$20
        inx
        inx
        cpx.w #!CREDITS_STARS*2
        bne .star
        rts

; ---------------------------------------------------------------------------
; 05:$5620 `credits_animateSamus`, by `credits_samusAnimState`: the 22 states.
; ---------------------------------------------------------------------------
CreditsAnimateSamus:
        sep #$20
        rep #$10
        lda.w !CrState
        rep #$20
        and.w #$00FF
        asl a
        tax
        sep #$20
        jmp (CreditsStates,x)

CreditsStates:
        dw .standingStart, .running, .unused, .spinRising, .spinFalling
        dw .wait, .wait, .wait, .wait, .wait, .wait, .wait     ; $05-$0B
        dw .wait, .wait, .wait, .wait, .wait, .wait            ; $0C-$11
        dw .untyingLast, .wait, .standingEnd, .hairWaving      ; $12-$15

; $15: her hair in the wind, a frame every sixteen.
.hairWaving
        lda !FrameCount                 ; $5658 `AND $10 / SWAP A`
        and.b #$10
        lsr a
        lsr a
        lsr a
        lsr a
        clc
        adc.b #$13
        jmp CreditsDrawSamus

; $14: the suit, standing for good.
.standingEnd
        lda.b #$0A
        jmp CreditsDrawSamus

; $05-$11 and $13, eleven routines of one shape: draw a frame, wait for the
; countdown's low byte, then set it for the next and step on. The frame and
; the next wait are `CreditsWaits`' row for the state.
.wait
        rep #$20
        lda.w !CrState
        and.w #$00FF
        sec
        sbc.w #!CREDITS_WAIT_FIRST
        asl a
        tax
        sep #$20
        lda.l CreditsWaits,x
        jsr CreditsDrawSamus
        lda !Countdown
        bne .out
        lda.l CreditsWaits+1,x
        sta !Countdown
        inc.w !CrState
.out
        rts

; $12, the hair's last frame, waits and then goes to $15 with no wait set.
.untyingLast
        lda.b #$12                      ; $5752
        jsr CreditsDrawSamus
        lda !Countdown
        bne .out
        lda.b #$15
        sta.w !CrState
        rts

; $04, falling: three down a frame until the lower bits aside she is at $60,
; then the countdown $20 and the ending, by the hour: under three, kneeling
; out of the suit ($05); otherwise in it ($13).
.spinFalling
        lda.w !CrSamusY                 ; $5779
        clc
        adc.b #$03
        sta.w !CrSamusY
        jsr .spinFrame
        lda.w !CrSamusY                 ; $578A
        and.b #$FC
        cmp.b #$60
        bne .out
        lda.b #$20                      ; $5791
        sta !Countdown
        lda.w !IgtHours                 ; $5796 `CP $03`
.bestHours                              ; the `credits` rung's fault patches this
        cmp.b #$03
        bcs +
        inc.w !CrState
        rts
+       lda.b #$13                      ; $57A5
        sta.w !CrState
        rts

; $03, rising: three up a frame until the lower bits aside she is at $E0,
; until the countdown runs out.
.spinRising
        lda.w !CrSamusY                 ; $57AB
        and.b #$F0
        cmp.b #$E0
        beq +
        lda.w !CrSamusY
        sec
        sbc.b #$03
        sta.w !CrSamusY
+       jsr .spinFrame
        lda !Countdown                  ; $57C2
        bne .out
        inc.w !CrState
        rts

; Both spins' frame: 4 + the counter's low two bits.
.spinFrame
        lda !FrameCount
        and.b #$03
        clc
        adc.b #$04
        jmp CreditsDrawSamus

; $00, standing in the suit: for good at seven hours or more; otherwise the
; $FF frames `prepareCredits` set, then the run.
.standingStart
        lda.b #$0A                      ; $57CF
        jsr CreditsDrawSamus
        lda.w !IgtHours                 ; $57D4 `CP $07 / RET NC`
        cmp.b #$07
        bcs .out2
        lda !Countdown
        bne .out2
        stz.w !CrRunCount               ; $57E0
        stz.w !CrRunFrame
        stz.w !CrDone                   ; $57E7, which is zero anyway
        ; $57EA-$57F1: $00 and then $12 both into the countdown's *high*
        ; byte, where the first surely meant the low. Kept: the low is zero
        ; here, so the run waits $1200 frames, which nothing reads.
        lda.b #$00
        sta !Countdown+1
        lda.b #$12
        sta !Countdown+1
        inc.w !CrState
.out2
        rts

; $01, running, a frame every six: for good at five hours or more; otherwise
; until the scroll is done, then the jump, with $40 in the countdown's low
; byte (`XOR A` stored there first, where the high was surely meant).
.running
        lda.w !CrRunCount               ; $57FB
        inc a
        sta.w !CrRunCount
        cmp.b #$06
        bcc +
        stz.w !CrRunCount
        lda.w !CrRunFrame               ; $5808
        inc a
        sta.w !CrRunFrame
        cmp.b #$04
        bne +
        stz.w !CrRunFrame
+       lda.w !CrRunFrame               ; $5816
        jsr CreditsDrawSamus
        lda.w !IgtHours                 ; $581C `CP $05 / RET NC`
        cmp.b #$05
        bcs .out2
        lda.w !CrDone
        beq .out2
        stz !Countdown                  ; $5828
        lda.b #$40
        sta !Countdown
        inc.w !CrState                  ; $5832, by two: past $02
        inc.w !CrState
        rts

; $02 is never entered: `.running` steps over it. On the Game Boy its entry
; is the address after the table's code, `credits_paletteFade`'s bytes.
.unused
        rts

; State $05-$13's frames and next waits, from `!CREDITS_WAIT_FIRST` on.
CreditsWaits:
        db $09,$30              ; $05 kneeling, out of the suit
        db $0B,$08              ; $06-$12, untying her hair
        db $0C,$10
        db $0D,$08
        db $0C,$08
        db $0B,$08
        db $0E,$08
        db $0B,$08
        db $0F,$08
        db $0B,$0A
        db $0E,$0A
        db $10,$0A
        db $11,$20
        db $12,$00              ; $12 is `.untyingLast`'s; unread
        db $08,$30              ; $13 kneeling, in the suit

; 05:$5989 `credits_drawSamus` and its table (05:$598D): frame A's sprites at
; the sprite position, from `CreditsDraws`' list for it. A list is ids to
; draw, in order; `!CRD_FLIP` sets `hSpriteAttr` to the X flip, `!CRD_LEFT`
; moves the X one left, `!CRD_PLAIN` clears the attribute, `!CRD_END` ends.
; Leaves 8-bit A.
CreditsDrawSamus:
        phx
        rep #$20
        and.w #$00FF
        asl a
        tax
        lda.l CreditsDraws,x
        tax
        sep #$20
.next
        lda.l CreditsDrawLists,x
        inx
        cmp.b #!CRD_END
        beq .done
        cmp.b #!CRD_FLIP
        bne +
        lda.b #$20                      ; `OAMF_XFLIP`
        sta.w !SprAttr
        bra .next
+       cmp.b #!CRD_PLAIN
        bne +
        stz.w !SprAttr
        bra .next
+       cmp.b #!CRD_LEFT
        bne +
        dec !SprX
        bra .next
+       sta !SpriteId
        phx
        jsr DrawNonGameSprite
        plx
        sep #$20
        bra .next
.done
        plx
        rts

CreditsDraws:
        dw CrdRunA-CreditsDrawLists, CrdRunB-CreditsDrawLists, CrdRunC-CreditsDrawLists, CrdRunD-CreditsDrawLists
        dw CrdJumpA-CreditsDrawLists, CrdJumpB-CreditsDrawLists, CrdJumpC-CreditsDrawLists, CrdJumpD-CreditsDrawLists
        dw CrdSuitKneel-CreditsDrawLists, CrdBareKneel-CreditsDrawLists, CrdSuitStand-CreditsDrawLists
        dw CrdBareA-CreditsDrawLists, CrdBareB-CreditsDrawLists, CrdBareC-CreditsDrawLists, CrdBareD-CreditsDrawLists
        dw CrdBareE-CreditsDrawLists, CrdBareF-CreditsDrawLists, CrdBareG-CreditsDrawLists, CrdBareH-CreditsDrawLists
        dw CrdWaveA-CreditsDrawLists, CrdWaveB-CreditsDrawLists
CreditsDrawLists:
CrdRunA:      db $08,$0B,!CRD_END                         ; $00, 05:$59B9
CrdRunB:      db $09,$0C,!CRD_END                         ; $01
CrdRunC:      db $0A,!CRD_FLIP,!CRD_LEFT,$0B,!CRD_PLAIN,!CRD_END     ; $02
CrdRunD:      db $09,!CRD_FLIP,$0C,!CRD_PLAIN,!CRD_END    ; $03
CrdJumpA:     db $1F,!CRD_END                             ; $04-$07, the spin
CrdJumpB:     db $20,!CRD_END
CrdJumpC:     db $21,!CRD_END
CrdJumpD:     db $22,!CRD_END
CrdSuitKneel: db $12,!CRD_END                             ; $08
CrdBareKneel:  db $11,!CRD_END                             ; $09
CrdSuitStand: db $07,!CRD_END                             ; $0A
CrdBareA:      db $0E,$0F,$10,!CRD_END                     ; $0B, hair up, hands down
CrdBareB:      db $0E,$13,$10,!CRD_END                     ; $0C, reaching up
CrdBareC:      db $14,$10,!CRD_END                         ; $0D, untying the bun
CrdBareD:      db $15,$0F,$10,!CRD_END                     ; $0E, head left
CrdBareE:      db $16,$0F,$10,!CRD_END                     ; $0F, head right
CrdBareF:      db $17,$0F,$10,!CRD_END                     ; $10-$12, unfurling
CrdBareG:      db $18,$0F,$10,!CRD_END
CrdBareH:      db $19,$0F,$10,!CRD_END
CrdWaveA:     db $18,$0F,$10,!CRD_END                     ; $13-$14, in the wind
CrdWaveB:     db $1A,$0F,$10,!CRD_END

; The image is whole banks (`snes_inject` asserts it): bank 1 padded to its end.
padbyte $FF
pad $01FFFF
        db $FF
